('00000000-0000-0000-0000-000000000001', 'general', 'Allgemein (bundesweit)', '通用（全德适用）', 0, NOW(), NOW()),
('5465e833-302f-4de6-9ca4-c082919dfa68', 'baden-wuerttemberg', 'Baden-Württemberg', '巴登-符腾堡州', 1, NOW(), NOW()),
