('54168ee6-a183-498b-a8e6-f87eb56d7600', 'brandenburg', 'Brandenburg', '勃兰登堡州', 4, NOW(), NOW()),
('5c624a64-8583-4cf3-a16c-49a13e681140', 'bremen', 'Bremen', '不来梅州', 5, NOW(), NOW()),
