('d375c3de-f95b-4ed4-8310-243ee89ea5da', 'mecklenburg-vorpommern', 'Mecklenburg-Vorpommern', '梅克伦堡-前波莫瑞州', 8, NOW(), NOW()),
('de31eecc-2df7-47d9-806d-088df47bc866', 'niedersachsen', 'Niedersachsen', '下萨克森州', 9, NOW(), NOW()),
('03b01569-7f32-4d4e-af84-6bc3f9bf97c7', 'nordrhein-westfalen', 'Nordrhein-Westfalen', '北莱茵-威斯特法伦州', 10, NOW(), NOW()),
('ab38653b-90d8-4858-82d4-010a5d3261ab', 'rheinland-pfalz', 'Rheinland-Pfalz', '莱茵兰-普法尔茨州', 11, NOW(), NOW()),
('48b1c98d-1d30-4e2d-82a6-9968aa986b8a', 'saarland', 'Saarland', '萨尔州', 12, NOW(), NOW()),
