('f0afa396-bd3b-4d7a-808b-192389673f3d', 'sachsen-anhalt', 'Sachsen-Anhalt', '萨克森-安哈尔特州', 14, NOW(), NOW()),
('b09aebcc-af92-4eb4-930f-261e53c5ed0d', 'schleswig-holstein', 'Schleswig-Holstein', '石勒苏益格-荷尔斯泰因州', 15, NOW(), NOW()),
('9ca749ab-6bbb-4e1b-a567-9b473df4dd61', 'thueringen', 'Thüringen', '图林根州', 16, NOW(), NOW())
INSERT INTO questions (id, state_id, question_de, question_cn, explanation, has_image, sort_order, created_at, updated_at) VALUES
  ('9acae2c4-4c1c-4761-8ea3-eee65e3d4089', '00000000-0000-0000-0000-000000000001', 'In Deutschland dürfen Menschen offen etwas gegen die Regierung sagen, weil …', '在德国，人们可以公开发表反对政府的言论，因为……', '《德国基本法》第5条规定了言论自由（Meinungsfreiheit），这是德国的一项基本人权，与宗 教自由、选举权等不同，它直接赋予人们公开表达政治观点的权利。因此，正确答案是“这里 有言论自由”。', 0, 1, NOW(), NOW()),
  ('da9d299f-706f-4ebd-beb3-db9c90b10b99', '00000000-0000-0000-0000-000000000001', 'In Deutschland können Eltern bis zum 14. Lebensjahr ihres Kindes entscheiden, ob es in der Schule a m …', '在德国，家长可以在孩子14岁前决定他们是否参加……', '德国学校的宗教课（Religionsunterricht）是可选择的，且未满14岁的学生由父母决定是否参 加。14岁之后，孩子可以自主决定。', 0, 2, NOW(), NOW()),
  ('cd16ba2d-ea04-4147-876d-ec9c63f0bad4', '00000000-0000-0000-0000-000000000001', 'Deutschland ist ein Rechtsstaat. Was ist damit gemeint?', '德国是一个法治国家。这是什么意思？', '“法治国家”（Rechtsstaat）意味着政府本身也受法律约束，没有任何人或机构可以凌驾于法 律之上。这是德国宪法的核心原则之一。', 0, 3, NOW(), NOW()),
  ('de9416b2-02e6-422f-ba4c-553800a3dd52', '00000000-0000-0000-0000-000000000001', 'Welches Recht gehört zu den Grundrechten in Deutschland?', '以下哪项属于德国的基本权利？', '德国基本法第5条明确规定了言论自由是公民的基本权利。武器拥有权、私刑和报复行为在德 国是受到限制甚至违法的。', 0, 4, NOW(), NOW()),
  ('ff479f75-e4b1-45a5-9ebf-1c86f345ddf6', '00000000-0000-0000-0000-000000000001', 'Wahlen in Deutschland sind frei. Was bedeutet das?', '德国的选举是自由的。这意味着……', '自由选举意味着选民自愿、无强迫地投票，是德国民主制度的基石。强制投票并不存在。', 0, 5, NOW(), NOW()),
  ('cdda64ad-9475-499a-8af3-043a5714ba00', '00000000-0000-0000-0000-000000000001', 'Wie heißt die deutsche Verfassung?', '德国宪法叫什么？', '德国宪法官方名称为“Grundgesetz für die Bundesrepublik Deutschland”（德意志联邦共和国基 本法）。', 0, 6, NOW(), NOW()),
  ('9800b98a-3bc7-46f8-90c6-caaa398c88c0', '00000000-0000-0000-0000-000000000001', 'Welches Recht gehört zu den Grundrechten, die nach der deutschen Verfassung garantiert werden? Das Recht auf …', '下列哪项是德国宪法所保障的基本权利？', '信仰和良心自由属于宪法保障的核心人权。《基本法》第4条保障宗教信仰的自由。', 0, 7, NOW(), NOW()),
  ('8f8d5f9d-84ce-4962-b1ca-efced53a0aa7', '00000000-0000-0000-0000-000000000001', 'Was steht nicht im Grundgesetz von Deutschland?', '下列哪项不在德国基本法中？', '“人人收入平等”并不属于宪法目标。德国保障平等权、言论自由和人性尊严。', 0, 8, NOW(), NOW()),
  ('bd68ddeb-bc87-462a-8848-89bcf5681801', '00000000-0000-0000-0000-000000000001', 'Welches Grundrecht gilt in Deutschland nur für Ausländerinnen/Ausländer? Das Grundrecht auf …', '下列哪项基本权利仅适用于外国人？', '避难权（Asylrecht）在德国是专为受政治迫害的外国人设计的基本权利。其他三项为普遍适用 的人权。', 0, 9, NOW(), NOW()),
  ('4893bcbe-519e-42c1-8746-449b8667564e', '00000000-0000-0000-0000-000000000001', 'Was ist mit dem deutschen Grundgesetz vereinbar?', '下列哪一项是符合德国基本法的？', '德国禁止死刑、酷刑和体罚。罚金是一种合法的刑罚手段。 好的，我们继续处理第11题到第20题，同样为你提供中德对照、正确答案和原因解析。', 0, 10, NOW(), NOW()),
  ('7c7292e1-9b75-43cd-846e-e401ad1afc09', '00000000-0000-0000-0000-000000000001', 'Wie wird die Verfassung der Bundesrepublik Deutschland genannt?', '德意志联邦共和国的宪法叫什么？', '德国宪法自1949年起被称为《Grundgesetz》（基本法），并未采用“Verfassung”（宪法）这 一词汇，是出于当时国家分裂背景下的政治考虑。', 0, 11, NOW(), NOW()),
  ('b5ebe076-4f0b-47e1-b2d6-eb2c39b76169', '00000000-0000-0000-0000-000000000001', 'Eine Partei im Deutschen Bundestag will die Pressefreiheit abschaffen. Ist das möglich?', '德国联邦议院中有政党想废除新闻自由。这可能吗？', '新闻自由属于《基本法》第5条所列的基本权利，不能被议会通过简单或加重多数修改或废 除。任何违宪的法律或提议都会被联邦宪法法院驳回。', 0, 12, NOW(), NOW()),
  ('500ab335-e561-49f3-b7ae-3c0561cb772d', '00000000-0000-0000-0000-000000000001', 'Im Parlament steht der Begriff "Opposition" für …', '在议会中，“反对派”是指……', '“Opposition”指的是不参与组建政府的议会党派，他们对政府起到监督作用，是民主制度的 重要组成部分。', 0, 13, NOW(), NOW()),
  ('f05ac74a-5166-41e7-a029-6d6f96e9fbb3', '00000000-0000-0000-0000-000000000001', 'Meinungsfreiheit in Deutschland heißt, dass ich …', '德国的言论自由意味着我可以……', '德国支持广泛的言论自由，但不包括人身攻击或宣扬极端主义。网络言论表达受到保护，前 提是不违法。', 0, 14, NOW(), NOW()),
  ('e8d3dc88-76d7-4867-b9f8-05b11e50be9c', '00000000-0000-0000-0000-000000000001', 'Was verbietet das deutsche Grundgesetz?', '德国基本法禁止什么？', '基本法第12条明确禁止强迫劳动（Zwangsarbeit），这是对人身自由的保障。其余选项都是合 法的个人选择。', 0, 15, NOW(), NOW()),
  ('731afd58-0a78-45e3-9dbd-20043646e891', '00000000-0000-0000-0000-000000000001', 'Wann ist die Meinungsfreiheit in Deutschland eingeschränkt?', '在什么时候，德国的言论自由会受到限制？', '言论自由不能侵犯他人名誉，散播虚假事实可能构成诽谤罪。对政府或宗教的批评通常是被 允许的，只要没有仇恨或虚假成分。', 0, 16, NOW(), NOW()),
  ('092a37a6-e00a-4234-a181-8cca4beabe25', '00000000-0000-0000-0000-000000000001', 'Die deutschen Gesetze verbieten …', '德国法律禁止……', '德国宪法规定政府必须在法律面前一视同仁（Gleichbehandlung）。前三项都是受到保护的基 本权利。', 0, 17, NOW(), NOW()),
  ('ffd55264-2238-45e0-ae63-060d5226a2b7', '00000000-0000-0000-0000-000000000001', 'Welches Grundrecht ist in Artikel 1 des Grundgesetzes der Bundesrepublik Deutschland garantiert?', '德国基本法第1条保障了哪项基本权利？', '第1条开头即写明：“Die Würde des Menschen ist unantastbar”（人的尊严不可侵犯），这被视 为整部宪法的基础和灵魂。', 0, 18, NOW(), NOW()),
  ('fad7fd01-a8f5-42f4-a428-4fc64d8ff05f', '00000000-0000-0000-0000-000000000001', 'Was versteht man unter dem Recht der "Freizügigkeit" in Deutschland?', '在德国，“居住自由权”指的是……', '居住自由（Freizügigkeit）是基本法第11条的内容，赋予公民在联邦境内自由迁徙和居住的权 利。', 0, 19, NOW(), NOW()),
  ('fbc0e91e-90e8-4fe5-8a20-46dbfbfda20a', '00000000-0000-0000-0000-000000000001', 'Eine Partei in Deutschland verfolgt das Ziel, eine Diktatur zu errichten. Sie ist dann …', '某政党在德国主张建立独裁统治。那么这个党是……', '根据德国宪法，任何反对自由民主基本秩序的政党都被视为“verfassungswidrig”（违宪）。 这样的政党可被联邦宪法法院取缔。', 0, 20, NOW(), NOW()),
  ('9ba07f2d-23b5-4ba9-a23e-3739381e2bfe', '00000000-0000-0000-0000-000000000001', 'Welches ist das Wappen der Bundesrepublik Deutschland?', '下列哪一个是德意志联邦共和国的国徽？', '德国的国徽是黑底金框上的黑色雄鹰（联邦鹰）。它象征德国的主权、团结和自由，图1展示 的正是这一官方标志。', 1, 21, NOW(), NOW()),
  ('f5e9ea77-7ba0-48c9-92f3-8221326e20d0', '00000000-0000-0000-0000-000000000001', 'Was für eine Staatsform hat Deutschland?', '德国属于哪种国家形态？', '德国是一个共和国（Republik），国家权力来源于人民，通过民主选举产生议会和政府，排除 君主和独裁体制。', 0, 22, NOW(), NOW()),
  ('61f250f5-4081-4424-aa25-dfb64bd4ca81', '00000000-0000-0000-0000-000000000001', 'In Deutschland sind die meisten Erwerbstätigen …', '在德国，大多数劳动者……', '德国大部分就业人口受雇于公司或政府机构，这反映了其发达的工业和服务经济结构。', 0, 23, NOW(), NOW()),
  ('430747e4-0996-45f5-841b-81402ef766ae', '00000000-0000-0000-0000-000000000001', 'Wie viele Bundesländer hat die Bundesrepublik Deutschland?', '德意志联邦共和国有多少个联邦州？', '德国共有16个联邦州（Bundesländer），包括3个城市州（柏林、汉堡、不来梅）和13个地区 州。', 0, 24, NOW(), NOW()),
  ('c99ef014-3327-46b8-a331-fc4e56b5dcdd', '00000000-0000-0000-0000-000000000001', 'Was ist kein Bundesland der Bundesrepublik Deutschland?', '以下哪个不是德国的联邦州？', 'Elsass-Lothringen 是法国的一个地区，不属于德国的16个联邦州之一。', 0, 25, NOW(), NOW()),
  ('1cb9da1f-0d6d-425e-a143-d4d869a680eb', '00000000-0000-0000-0000-000000000001', 'Deutschland ist …', '德国是……', '德国宪法规定其为“民主和社会联邦国家”（Art. 20 GG），体现人民主权和社会公平原则。', 0, 26, NOW(), NOW()),
  ('6e21fa28-aa65-4169-84e2-c4dc24ab2bea', '00000000-0000-0000-0000-000000000001', 'Deutschland ist …', '德国是……', '德国是由16个联邦州组成的联邦国家，每个州拥有宪法和立法权，但整体统一于联邦宪法之 下。', 0, 27, NOW(), NOW()),
  ('65c396a3-a8c3-4bdf-b05d-66daf3e36bd5', '00000000-0000-0000-0000-000000000001', 'Wer wählt in Deutschland die Abgeordneten zum Bundestag?', '在德国，谁选举联邦议会的议员？', '联邦议会（Bundestag）议员是由具有投票权的德国公民通过普选直接选出的。', 0, 28, NOW(), NOW()),
  ('5e7a2600-73b5-43f1-954a-923803d591af', '00000000-0000-0000-0000-000000000001', 'Welches Tier ist das Wappentier der Bundesrepublik Deutschland?', '德国国徽上的动物是哪一种？', '联邦鹰（Bundesadler）是德国的国徽动物，自魏玛共和国以来一直作为国家的象征。', 0, 29, NOW(), NOW()),
  ('2113709b-4ac0-44f4-afde-6a9e6c0804c0', '00000000-0000-0000-0000-000000000001', 'Was ist kein Merkmal unserer Demokratie?', '以下哪项不是我们民主制度的特征？', '新闻自由是民主的基本要素，而新闻审查是非民主或独裁国家的特征。', 0, 30, NOW(), NOW()),
  ('717f58f1-6cd2-42a8-8130-ae34305b5744', '00000000-0000-0000-0000-000000000001', 'Die Zusammenarbeit von Parteien zur Bildung einer Regierung nennt man in Deutschland …', '在德国，政党为了组成政府而进行合作，被称为……', '如果单个政党没有绝对多数席位，就必须与其他政党联合组阁，这种政党合作关系称为“Koa lition”。', 0, 31, NOW(), NOW()),
  ('0abb5640-13d6-4b72-871e-b31d88855f4e', '00000000-0000-0000-0000-000000000001', 'Was ist keine staatliche Gewalt in Deutschland?', '下列哪项不是德国的国家权力机构？', '德国实行“三权分立”：立法（Legislative）、行政（Exekutive）、司法（Judikative）。新闻 虽被称为“第四权力”，但不属于国家机关。', 0, 32, NOW(), NOW()),
  ('5ff94e5f-9593-4cd9-8f35-f2eddb9fe59e', '00000000-0000-0000-0000-000000000001', 'Welche Aussage ist richtig? In Deutschland …', '哪一项说法是正确的？在德国……', '根据德国《基本法》，国家与宗教团体分离，国家不得干预宗教自由，也不得建立国教。', 0, 33, NOW(), NOW()),
  ('96ba5256-b46b-4905-a0ed-7626466cbc15', '00000000-0000-0000-0000-000000000001', 'Was ist Deutschland nicht?', '德国不是什么？', '德国是一个民主共和国，联邦总统为国家元首，不设国王，因此不是“Monarchie”。', 0, 34, NOW(), NOW()),
  ('3a21d182-c46c-45ab-a064-78a003a7fe68', '00000000-0000-0000-0000-000000000001', 'Womit finanziert der deutsche Staat die Sozialversicherung?', '德国国家通过什么方式为社会保险提供资金？', '社会保险（养老、医疗、失业等）主要由雇主和雇员共同缴纳的“Sozialabgaben”来资助。', 0, 35, NOW(), NOW()),
  ('b346c0ed-bf45-41e3-be19-3fd3d6540467', '00000000-0000-0000-0000-000000000001', 'Welche Maßnahme schafft in Deutschland soziale Sicherheit?', '以下哪一项有助于在德国建立社会保障？', '社会保险制度是德国福利国家的重要支柱，其中Krankenversicherung（医疗保险）是核心组成 部分。', 0, 36, NOW(), NOW()),
  ('df1319d1-8406-4c7a-a30f-3b6095e1a6e3', '00000000-0000-0000-0000-000000000001', 'Wie werden die Regierungschefinnen/Regierungschefs der meisten Bundesländer in Deutschland genann t?', '德国大多数联邦州的政府首脑称为什么？', '除了城市州如汉堡、柏林用“Bürgermeister”，其他州的最高行政长官叫“Ministerpräsiden t”。', 0, 37, NOW(), NOW()),
  ('02928d25-d8e5-4aff-a5d8-63bc1219d326', '00000000-0000-0000-0000-000000000001', 'Die Bundesrepublik Deutschland ist ein demokratischer und sozialer …', '德意志联邦共和国是一个民主和社会的……', '德国是Bundesstaat，由16个联邦州组成，拥有一定的自治权。', 0, 38, NOW(), NOW()),
  ('15632629-0169-458a-8339-e94aa87424c9', '00000000-0000-0000-0000-000000000001', 'Was hat jedes deutsche Bundesland?', '每个德国联邦州都拥有……', '联邦州不能自行处理外交和国防事务，但每个州都有自己的州议会和政府。', 0, 39, NOW(), NOW()),
  ('9908e951-542c-4ac2-98ca-41377b774375', '00000000-0000-0000-0000-000000000001', 'Mit welchen Worten beginnt die deutsche Nationalhymne?', '德国国歌以哪句歌词开头？', '德国国歌是《德意志之歌》第三段，开头为“Einigkeit und Recht und Freiheit”（团结、正义与 自由）。', 0, 40, NOW(), NOW()),
  ('e87bae45-082a-4d1f-8cf3-d3068d9be6bd', '00000000-0000-0000-0000-000000000001', 'Warum gibt es in einer Demokratie mehr als eine Partei?', '为什么民主国家有多个政党？', '多党制是民主政治的核心，能确保各类民意得到政治表达和代表。', 0, 41, NOW(), NOW()),
  ('51d7312d-6b7e-4cf3-b2d2-ac25d5d71a2b', '00000000-0000-0000-0000-000000000001', 'Wer beschließt in Deutschland ein neues Gesetz?', '在德国，谁决定新法律的通过？', '新法律的制定由联邦议院（Bundestag）及在部分情况下联邦参议院（Bundesrat）表决通过， 属于立法机关职责。', 0, 42, NOW(), NOW()),
  ('71a60f4a-4d3d-4cf1-ad42-7c47278ffef4', '00000000-0000-0000-0000-000000000001', 'Wann kann in Deutschland eine Partei verboten werden?', '在什么情况下，德国的政党可以被取缔？', '根据《基本法》第21条，若政党旨在破坏自由民主基本秩序，可被联邦宪法法院裁定为违宪 并取缔。', 0, 43, NOW(), NOW()),
  ('cd9807b8-15df-493b-beb6-4d6ffe3d73cb', '00000000-0000-0000-0000-000000000001', 'Wen kann man als Bürgerin/Bürger in Deutschland nicht direkt wählen?', '在德国，作为公民不能直接选举以下哪位？', '联邦总统由联邦大会（Bundesversammlung）间接选出，而不是全民直选。', 0, 44, NOW(), NOW()),
  ('745d8222-dcc7-4f48-8af7-bd70231408d2', '00000000-0000-0000-0000-000000000001', 'Zu welcher Versicherung gehört die Pflegeversicherung?', '护理保险属于哪类保险？', '“Pflegeversicherung”（护理保险）是德国五大法定社会保险之一（与养老、医疗、失业、工 伤并列）。', 0, 45, NOW(), NOW()),
  ('7b94d206-3ba9-4e42-8e8e-695d21d4c620', '00000000-0000-0000-0000-000000000001', 'Der deutsche Staat hat viele Aufgaben. Welche Aufgabe gehört dazu?', '德国政府有许多职责，以下哪一项属于政府职能？', '基础设施和公共教育属于国家职能，而商品销售和制造业由私营企业承担。', 0, 46, NOW(), NOW()),
  ('4e3d3cb2-bcd4-44b2-83d5-f275c1bebe75', '00000000-0000-0000-0000-000000000001', 'Welche Aufgabe gehört nicht zum Staat in Deutschland?', '以下哪项不属于德国国家的职责？', '德国政府负责基本民生、文化、体育支持等，但不会承担个人娱乐或旅游费用。', 0, 47, NOW(), NOW()),
  ('6eaef167-616a-4fd9-b669-472bb6ba78fc', '00000000-0000-0000-0000-000000000001', 'Welches Organ gehört nicht zu den Verfassungsorganen Deutschlands?', '以下哪个机构不属于德国的宪法机关？', '德国宪法机关包括：联邦议会、联邦参议院、联邦总统、联邦政府、联邦宪法法院。公民大 会不具备宪法机关地位。', 0, 48, NOW(), NOW()),
  ('2d0f324e-4ac1-4dc8-bc54-879adcd02afb', '00000000-0000-0000-0000-000000000001', 'Wer bestimmt in Deutschland die Schulpolitik?', '谁决定德国的教育政策？', '教育政策属于“文化主权”（Kulturhoheit der Länder），由联邦州独立负责，因此各州的学校 体系略有不同。', 0, 49, NOW(), NOW()),
  ('07e8cfce-b863-4821-b3f9-8ea5858debf2', '00000000-0000-0000-0000-000000000001', 'Die Wirtschaftsform in Deutschland nennt man …', '德国的经济体制被称为……', '“soziale Marktwirtschaft”（社会市场经济）结合自由市场机制和社会保障制度，是德国经济 政策的核心理念。', 0, 50, NOW(), NOW()),
  ('3b718954-57dd-45ed-92a8-cb30a3448775', '00000000-0000-0000-0000-000000000001', 'Zu einem demokratischen Rechtsstaat gehört es nicht, dass …', '以下哪项不符合民主法治国家的原则？', '法治国家必须保障人权，不能接受任何私人机构任意逮捕公民。合法逮捕必须由国家机关依 法律程序执行。', 0, 51, NOW(), NOW()),
  ('ab24e93e-a190-4b87-a7b0-7ae00bab5e62', '00000000-0000-0000-0000-000000000001', 'Was bedeutet „Volkssouveränität“? Alle Staatsgewalt geht vom ...', '“人民主权”是什么意思？所有国家权力源于……', '德国基本法第一条明确：Alle Staatsgewalt geht vom Volke aus（一切国家权力来自人民），这 是民主的核心。', 0, 52, NOW(), NOW()),
  ('fb9d8cd4-c39c-4c4a-b06d-095b82bf8c1e', '00000000-0000-0000-0000-000000000001', 'Was bedeutet „Rechtsstaat“ in Deutschland?', '“法治国家”在德国意味着……', '“Rechtsstaat”是指法律至上，政府本身也必须遵守法律。不是专政或任意执政。', 0, 53, NOW(), NOW()),
  ('03522bd8-31e6-4184-9b07-65424aa5d81f', '00000000-0000-0000-0000-000000000001', 'Was ist keine staatliche Gewalt in Deutschland?', '以下哪项不是德国的国家权力？', '三权分立是德国宪政结构的基础。“Direktive”并非正式国家机关。', 0, 54, NOW(), NOW()),
  ('7a19aaed-6d89-4b88-9e42-88ccf4b3a068', '00000000-0000-0000-0000-000000000001', 'Was zeigt dieses Bild? （图：联邦议会大厦）', '这张图展示的是？', '图像是柏林Reichstagsgebäude，为德国联邦议会（Bundestag）所在地，顶部透明圆顶是其标 志。', 0, 55, NOW(), NOW()),
  ('e280a0bb-23f0-42cd-a543-8dd37cc8de15', '00000000-0000-0000-0000-000000000001', 'Welches Amt gehört in Deutschland zur Gemeindeverwaltung?', '以下哪个部门属于德国的市政行政机构？', '“Ordnungsamt”属于地方市政行政部门，处理噪音、非法停车、公共秩序等事务。', 0, 56, NOW(), NOW()),
  ('6f396075-fe88-4d30-956e-82787d7b5de2', '00000000-0000-0000-0000-000000000001', 'Wer wird meistens zur Präsidentin/zum Präsidenten des Deutschen Bundestages gewählt?', '谁通常被选为德国联邦议会议长？', '议长由议席最多的党团推选产生，主持议会事务、保持中立。', 0, 57, NOW(), NOW()),
  ('80843908-a088-4fc5-abaf-4b2327072e2a', '00000000-0000-0000-0000-000000000001', 'Wer ernennt in Deutschland die Ministerinnen/die Minister der Bundesregierung?', '德国联邦部长由谁任命？', '联邦总统根据总理提议任命内阁成员，这是宪法规定程序。', 0, 58, NOW(), NOW()),
  ('7c625d34-d242-43a8-9948-4957f56fcaa2', '00000000-0000-0000-0000-000000000001', 'Vor wie vielen Jahren gab es erstmals eine jüdische Gemeinde auf dem Gebiet des heutigen Deutschland s?', '在现在德国的领土上，犹太社区最早出现于多少年前？', '约在公元321年，罗马皇帝康斯坦丁批准犹太人在科隆定居，是德国有记载的最早犹太社区。', 0, 59, NOW(), NOW()),
  ('45ed2c97-0b6d-4287-9732-976e14b34938', '00000000-0000-0000-0000-000000000001', 'In Deutschland gehören der Bundestag und der Bundesrat zur …', '在德国，联邦议会和联邦参议院属于……', 'Bundestag（联邦议会）和 Bundesrat（联邦参议院）共同构成德国的立法机构（Legislative）， 负责起草与通过法律。', 0, 60, NOW(), NOW()),
  ('2c7fb4ec-d225-481b-b18a-d52213adf112', '00000000-0000-0000-0000-000000000001', 'Was bedeutet „Volkssouveränität“?', '“人民主权”意味着什么？', '“Volkssouveränität”是德国民主的基本原则，出自《基本法》第20条第2款：“Alle Staatsgewal t geht vom Volke aus.”', 0, 61, NOW(), NOW()),
  ('bfa4174e-721a-4a5d-8ea3-f3cb5e052701', '00000000-0000-0000-0000-000000000001', 'Wenn das Parlament eines deutschen Bundeslandes gewählt wird, nennt man das …', '当选举一个德国联邦州的议会时，这叫做……', '每个联邦州有自己的议会（Landtag），选举这个州议会称为“Landtagswahl”。', 0, 62, NOW(), NOW()),
  ('ce99778b-1769-4b07-b1b3-7b658a2f76e2', '00000000-0000-0000-0000-000000000001', 'Was gehört in Deutschland nicht zur Exekutive?', '下列哪一项不属于德国的行政机关？', '行政机关（Exekutive）执行法律，但法院（Gerichte）属于司法机关（Judikative）。', 0, 63, NOW(), NOW()),
  ('44b2119c-3ad3-47fc-936d-2480fa24106a', '00000000-0000-0000-0000-000000000001', 'Die Bundesrepublik Deutschland ist heute gegliedert in …', '现今的德国由以下哪些层级组成？', '德国行政结构为三级体系：联邦（Bund）、州（Länder）、地方（Kommunen），体现联邦制 国家特征。', 0, 64, NOW(), NOW()),
  ('e992a5ec-e0e6-470a-be5a-03e4ecf76c9b', '00000000-0000-0000-0000-000000000001', 'Es gehört nicht zu den Aufgaben des Deutschen Bundestages, …', '以下哪项不是联邦议会的职责？', '内阁（Bundeskabinett）是由联邦总理提名、联邦总统任命的，不是由议会组成的。', 0, 65, NOW(), NOW()),
  ('6e4c3131-a1c5-4ab4-a235-50b6c4652728', '00000000-0000-0000-0000-000000000001', 'Welche Städte haben die größten jüdischen Gemeinden in Deutschland?', '下列哪些城市拥有德国最大的犹太社区？', '柏林和慕尼黑是德国犹太人口最多的城市，拥有活跃的社区、会堂和文化生活。', 0, 66, NOW(), NOW()),
  ('766f5ea2-428b-4904-b903-014abf88aadb', '00000000-0000-0000-0000-000000000001', 'Was ist in Deutschland vor allem eine Aufgabe der Bundesländer?', '下列哪项主要是德国各联邦州的职责？', '教育属于州政府专属权限，各州可独立设置教育体系、课程内容等。', 0, 67, NOW(), NOW()),
  ('5e880437-3393-420b-aa4a-f9e57937157e', '00000000-0000-0000-0000-000000000001', 'Warum kontrolliert der Staat in Deutschland das Schulwesen?', '为什么德国国家要监管学校教育？', '德国《基本法》第7条明确规定，国家有责任监管整个教育体系，尽管实施层面由各州负责。', 0, 68, NOW(), NOW()),
  ('c3948bcd-78f2-4af5-bee6-5171dbe89b80', '00000000-0000-0000-0000-000000000001', 'Die Bundesrepublik Deutschland hat einen dreistufigen Verwaltungsaufbau. Wie heißt die unterste politis che Stufe?', '德国行政系统分为三级，最基层的政治层级叫什么？', '德国的最基层行政单位是Gemeinden（市镇），负责日常居民服务，如户籍、建筑、学校 等。', 0, 69, NOW(), NOW()),
  ('b43f02cd-c752-41a0-89f8-8450e4fff9e2', '00000000-0000-0000-0000-000000000001', 'Der deutsche Bundespräsident Gustav Heinemann gibt Helmut Schmidt 1974 die Ernennungsurkunde z um deutschen Bundeskanzler. Was gehört zu den Aufgaben des deutschen Bundespräsidenten?', '1974年，德国总统海涅曼将总理任命书交给施密特。以下哪项属于德国总统的职责？', '联邦总统职责主要是礼仪性和形式性，其中重要任务是根据议会力量提名总理候选人，由议 会表决。', 0, 70, NOW(), NOW()),
  ('5f68f618-24ec-496a-9387-57b593188fc5', '00000000-0000-0000-0000-000000000001', 'Wo hält sich die deutsche Bundeskanzlerin/der deutsche Bundeskanzler am häufigsten auf?', '德国总理最常待在哪里？', '德国自1999年起将政府迁至柏林，联邦总理在柏林办公，并在那里参与议会会议，因此总理 最常待在柏林。', 0, 71, NOW(), NOW()),
  ('e3b1a2f4-0e65-4ca4-81c5-cb587dbf0356', '00000000-0000-0000-0000-000000000001', 'Wie heißt die jetzige Bundeskanzlerin/der jetzige Bundeskanzler von Deutschland?', '现任德国总理叫什么名字？', 'Friedrich Merz 自2025年5月6日担任德国总理', 0, 72, NOW(), NOW()),
  ('f2f65c64-2c45-4302-beec-ad5273cbed97', '00000000-0000-0000-0000-000000000001', 'Die beiden größten Fraktionen im Deutschen Bundestag heißen zurzeit …', '目前德国联邦议院中最大的两个党团是……', '2025年2月大选结果，德国最大的两个党团是CDU/CSU（联盟党）和AfD（选择党）。', 0, 73, NOW(), NOW()),
  ('d6790aa9-033b-47c2-8ffb-322b3a4615fb', '00000000-0000-0000-0000-000000000001', 'Wie heißt das Parlament für ganz Deutschland?', '德国全国性的议会叫什么？', '联邦议院（Bundestag）是德国的国家议会，代表全国立法权，与联邦参议院共同负责立法。', 0, 74, NOW(), NOW()),
  ('37f7ba67-c421-4896-9a75-7e53df39036e', '00000000-0000-0000-0000-000000000001', 'Wie heißt Deutschlands heutiges Staatsoberhaupt?', '现任德国国家元首是谁？', '德国的国家元首是联邦总统，现任总统为Frank-Walter Steinmeier，自2017年起担任此职。', 0, 75, NOW(), NOW()),
  ('82cdd812-74d2-4415-9da7-079bd0559ee8', '00000000-0000-0000-0000-000000000001', 'Was bedeutet die Abkürzung CDU in Deutschland?', '德国缩写CDU代表什么？', 'CDU 是德国主要的中右翼政党，全称为“基督教民主联盟”（Christlich Demokratische Unio n）。', 0, 76, NOW(), NOW()),
  ('aa16de33-e8f7-4be5-bbdf-45afd5057739', '00000000-0000-0000-0000-000000000001', 'Was ist die Bundeswehr?', '什么是“联邦国防军”（Bundeswehr）？', 'Bundeswehr 是德国的正规军队，负责国家的防御与国际维和任务。', 0, 77, NOW(), NOW()),
  ('5ab306c1-59e2-4f1e-aed7-31c06aeecc30', '00000000-0000-0000-0000-000000000001', 'Was bedeutet die Abkürzung SPD?', '德国缩写SPD代表什么？', 'SPD 是德国的主要中左翼政党，全称是“德国社会民主党”。', 0, 78, NOW(), NOW()),
  ('5aff5566-cdf8-428a-a5b1-aed687f4db02', '00000000-0000-0000-0000-000000000001', 'Was bedeutet die Abkürzung FDP in Deutschland?', '德国缩写FDP代表什么？', 'FDP 是德国的中间偏右政党，强调自由市场和公民自由。', 0, 79, NOW(), NOW()),
  ('bcf00822-bc75-47e1-bb11-095f6f4640b8', '00000000-0000-0000-0000-000000000001', 'Welches Gericht in Deutschland ist zuständig für die Auslegung des Grundgesetzes?', '哪个法院负责解释德国基本法（宪法）？', '德国联邦宪法法院（Bundesverfassungsgericht）负责基本法的解释和宪法争议的裁决。', 0, 80, NOW(), NOW()),
  ('5a0a2176-d377-46be-b950-7c2f66eff02c', '00000000-0000-0000-0000-000000000001', 'Wer wählt die Bundeskanzlerin/den Bundeskanzler in Deutschland?', '在德国，谁选举联邦总理？', '联邦议院的议员通过投票选举总理，而不是由公民直接选出。这是议会制民主的特点。', 0, 81, NOW(), NOW()),
  ('4b040ba7-f5d3-42ae-8a4d-4670aa612c3d', '00000000-0000-0000-0000-000000000001', 'Wer leitet das deutsche Bundeskabinett?', '谁领导德国的联邦内阁？', '联邦总理是政府首脑，负责主持内阁会议并决定政府政策方向。', 0, 82, NOW(), NOW()),
  ('3ebe3e00-d72e-4810-88a5-1279e6395fee', '00000000-0000-0000-0000-000000000001', 'Wer wählt die deutsche Bundeskanzlerin/den deutschen Bundeskanzler?', '谁选举德国总理？', '和第81题相同，德国总理由联邦议院议员选出，而非直接由选民决定。', 0, 83, NOW(), NOW()),
  ('21c5ee0b-6937-4e1a-9024-d394883b7f38', '00000000-0000-0000-0000-000000000001', 'Welche Hauptaufgabe hat die deutsche Bundespräsidentin/der deutsche Bundespräsident? Sie/Er …', '德国总统的主要职责是什么？', '德国总统是国家元首，主要职责是象征性和代表性的，例如任命官员、接待外宾等，不直接 参与日常执政。', 0, 84, NOW(), NOW()),
  ('e47a877c-47c3-488f-9de5-14d7eb70de47', '00000000-0000-0000-0000-000000000001', 'Wer bildet den deutschen Bundesrat?', '谁组成德国联邦参议院（Bundesrat）？', '联邦参议院是各州政府代表的机构，反映联邦制结构，主要用于参与立法、维护各州利益。', 0, 85, NOW(), NOW()),
  ('7146d95c-bf63-449a-9947-9148026d177c', '00000000-0000-0000-0000-000000000001', 'Wer wählt in Deutschland die Bundespräsidentin/den Bundespräsidenten?', '谁选举德国联邦总统？', '联邦总统由联邦大会选出，联邦大会由联邦议员和州议会代表共同组成，仅为选举总统而设 立的机构。', 0, 86, NOW(), NOW()),
  ('0a97c635-b5b6-4f6d-bd24-283e46da4516', '00000000-0000-0000-0000-000000000001', 'Wer ist das Staatsoberhaupt der Bundesrepublik Deutschland?', '谁是德意志联邦共和国的国家元首？', '国家元首具有象征意义，代表国家对外发言的是总统，不是总理。', 0, 87, NOW(), NOW()),
  ('82970088-7229-4d30-af0d-09004ad44daa', '00000000-0000-0000-0000-000000000001', 'Die parlamentarische Opposition im Deutschen Bundestag …', '德国联邦议院中的议会反对派……', '反对党在议会中的职责之一就是通过质询、调查、辩论等方式监督执政党，保障民主运行。', 0, 88, NOW(), NOW()),
  ('49814f90-fb4b-4af0-99bb-9e0343953207', '00000000-0000-0000-0000-000000000001', 'Wie nennt man in Deutschland die Vereinigung von Abgeordneten einer Partei im Parlament?', '德国议会中，同一政党议员组成的团体被称为什么？', '“Fraktion”是同一政党或政治立场相近的议员在议会中组成的组织单位，便于协调和集体决 策。', 0, 89, NOW(), NOW()),
  ('056da1cd-c690-4488-9a18-6c414cb58ad6', '00000000-0000-0000-0000-000000000001', 'Die deutschen Bundesländer wirken an der Gesetzgebung des Bundes mit durch …', '德国各联邦州通过什么机构参与联邦立法？', '联邦参议院由各州政府代表组成，是州在联邦立法中的代表机构，尤其在涉及州权事务时具 有否决权。', 0, 90, NOW(), NOW()),
  ('462c78fc-3fa7-4e69-980f-e95f3f1d452e', '00000000-0000-0000-0000-000000000001', 'In Deutschland kann ein Regierungswechsel in einem Bundesland Auswirkungen auf die Bundespolitik h aben. Das Regieren wird …', '在德国，一个联邦州的政权更替可能会影响联邦政治。执政将变得……', '联邦参议院在立法中拥有否决权。如果某州政党更替导致参议院中政府失去多数席位，将使 联邦立法变得更困难。', 0, 91, NOW(), NOW()),
  ('d6dc134e-0a96-4f44-8b82-64aadb306160', '00000000-0000-0000-0000-000000000001', 'Was bedeutet die Abkürzung CSU in Deutschland?', '在德国，缩写CSU是什么意思？', 'CSU（Christlich-Soziale Union）是德国的保守党派，仅活跃于巴伐利亚州，长期与CDU合作。', 0, 92, NOW(), NOW()),
  ('e5bae369-0b1e-4da7-b7ee-93f68fe583e6', '00000000-0000-0000-0000-000000000001', 'Je mehr "Zweitstimmen" eine Partei bei einer Bundestagswahl bekommt, desto …', '在联邦议院选举中，一个政党获得的“第二选票”越多，就……', '德国的“第二选票”决定政党在议会中所占的比例席位，是决定议会席位的关键。', 0, 93, NOW(), NOW()),
  ('52dd584b-a583-4e3c-9834-1001ac3b7788', '00000000-0000-0000-0000-000000000001', 'Ab welchem Alter darf man in Deutschland an der Wahl zum Deutschen Bundestag teilnehmen?', '在德国，公民从几岁起可以参加联邦议院选举？', '根据德国法律，年满18岁且拥有德国国籍的公民才有资格参加联邦议院选举。', 0, 94, NOW(), NOW()),
  ('deef5fd2-7ce8-4ec1-8ea7-20a5e2cf848b', '00000000-0000-0000-0000-000000000001', 'Was gilt für die meisten Kinder in Deutschland?', '德国大多数儿童受什么法律约束？', '在德国，儿童通常从6岁起必须接受至少9至10年的义务教育，这是法律规定的。', 0, 95, NOW(), NOW()),
  ('9a741c6e-1161-4208-a324-d4223346a63f', '00000000-0000-0000-0000-000000000001', 'Wie kann jemand, der den Holocaust leugnet, bestraft werden?', '否认大屠杀的人在德国会受到怎样的惩罚？', '在德国，否认纳粹大屠杀属于刑事犯罪（Volksverhetzung），最高可判五年监禁。', 0, 96, NOW(), NOW()),
  ('37521ed7-b706-4dc2-9a43-fae7c7f1bc5c', '00000000-0000-0000-0000-000000000001', 'Was bezahlt man in Deutschland automatisch, wenn man fest angestellt ist?', '在德国，如果有固定工作，会自动缴纳什么？', '固定雇员会自动从工资中扣除社保费用，包含医疗、养老、失业和护理保险。', 0, 97, NOW(), NOW()),
  ('b290895a-e2bc-4fd3-b313-d67ccd4de78c', '00000000-0000-0000-0000-000000000001', 'Wenn Abgeordnete im Deutschen Bundestag ihre Fraktion wechseln, …', '如果联邦议院中的议员更换了所属党团，会发生什么？', '如果有多个议员退党或转投反对党，可能导致执政联盟失去议会多数，从而危及政府稳定。', 0, 98, NOW(), NOW()),
  ('9c95c560-6243-48ce-bf87-ffff3168ab03', '00000000-0000-0000-0000-000000000001', 'Wer bezahlt in Deutschland die Sozialversicherungen?', '在德国，社会保险由谁支付？', '德国社保费用由雇主和雇员按比例分担，是工资结构的一部分。', 0, 99, NOW(), NOW()),
  ('c974e099-cb66-4919-9586-4611e35bd19c', '00000000-0000-0000-0000-000000000001', 'Was gehört nicht zur gesetzlichen Sozialversicherung?', '下列哪项不属于德国法定社会保险？', '人寿保险属于私人商业保险，不是法定社保范围。法定社保主要包括医疗、养老、护理、失 业、工伤五项。', 0, 100, NOW(), NOW()),
  ('42124e5c-6820-40e3-bb4e-338de502ca2e', '00000000-0000-0000-0000-000000000001', 'Gewerkschaften sind Interessenverbände der …', '工会是以下哪一群体的利益代表组织？', '德国的工会（Gewerkschaften）是为劳动者争取工资、工作条件和权利的组织，代表雇员利 益。', 0, 101, NOW(), NOW()),
  ('af05f3ec-975a-47cd-abde-13d968cd142a', '00000000-0000-0000-0000-000000000001', 'Womit kann man in der Bundesrepublik Deutschland geehrt werden, wenn man auf politischem, wirtsch aftlichem, kulturellem, geistigem oder sozialem Gebiet eine besondere Leistung erbracht hat? Mit dem …', '在政治、经济、文化、精神或社会领域作出特殊贡献的人在德国可获得什么荣誉？', '“联邦功绩十字勋章”（Bundesverdienstkreuz）是德国授予个人的最高荣誉，表彰其对社会的 杰出贡献。', 0, 102, NOW(), NOW()),
  ('9d3271d4-9a1c-4211-832b-c020086f3ecc', '00000000-0000-0000-0000-000000000001', 'Was wird in Deutschland als "Ampelkoalition" bezeichnet? Die Zusammenarbeit …', '德国所说的“红绿灯联盟”是指哪种联合政府？', '因三党党徽色分别为红、黄、绿，故SPD、FDP、绿党的执政联盟被称为“红绿灯联盟”（A mpelkoalition）。', 0, 103, NOW(), NOW()),
  ('002e154e-d04f-4af9-acaf-db5c65a6cf6f', '00000000-0000-0000-0000-000000000001', 'Eine Frau in Deutschland verliert ihre Arbeit. Was darf nicht der Grund für diese Entlassung sein?', '在德国，一位女性失去工作。以下哪一项不能作为解雇她的理由？', '德国法律禁止因怀孕而解雇女性，孕期与产假期间享有特别的劳动保护。', 0, 104, NOW(), NOW()),
  ('3329e8c2-34b7-419a-be45-3abcea3fb645', '00000000-0000-0000-0000-000000000001', 'Was ist eine Aufgabe von Wahlhelferinnen/Wahlhelfern in Deutschland?', '在德国，选举助理的职责之一是什么？', '选举助理（Wahlhelfer）在投票结束后负责当场公开计票，确保选举公正。', 0, 105, NOW(), NOW()),
  ('3888b64d-e564-4c0d-a0e3-1a6b9057b02f', '00000000-0000-0000-0000-000000000001', 'In Deutschland helfen ehrenamtliche Wahlhelferinnen und Wahlhelfer bei den Wahlen. Was ist eine Auf gabe von Wahlhelferinnen/Wahlhelfern?', '德国的志愿选举助理在选举中帮助完成哪些工作？', '志愿选举助理的最关键职责是计票，这确保了德国选举的透明和公正。', 0, 106, NOW(), NOW()),
  ('a8cdfffb-48fa-485f-a214-2bb1c498c5ae', '00000000-0000-0000-0000-000000000001', 'Für wie viele Jahre wird der Bundestag in Deutschland gewählt?', '德国联邦议院的任期是几年？', '德国联邦议院每届任期为4年，选举通常每4年举行一次。', 0, 107, NOW(), NOW()),
  ('114eceac-d873-44fc-9d64-828f7676e620', '00000000-0000-0000-0000-000000000001', 'Bei einer Bundestagswahl in Deutschland darf jede/jeder wählen, die/der …', '在德国，谁有资格参与联邦议院选举？', '联邦选举法规定，年满18岁的德国公民具有选举权。', 0, 108, NOW(), NOW()),
  ('1cca72d4-9037-404c-9504-ed41dd4d553b', '00000000-0000-0000-0000-000000000001', 'Wie oft gibt es normalerweise Bundestagswahlen in Deutschland?', '德国的联邦议院通常多久举行一次选举？', '根据《基本法》和《联邦选举法》，德国联邦议院选举每四年举行一次。', 0, 109, NOW(), NOW()),
  ('519647eb-3a08-41d5-8285-1419d45684e7', '00000000-0000-0000-0000-000000000001', 'Für wie viele Jahre wird der Bundestag in Deutschland gewählt?', '德国联邦议院的任期是几年？', '再次确认：德国联邦议院每届任期为4年，与前面第107题一致。', 0, 110, NOW(), NOW()),
  ('d4ab25c8-b9e3-4bed-9812-dcdde9a9655f', '00000000-0000-0000-0000-000000000001', 'Welche Handlungen mit Bezug auf den Staat Israel sind in Deutschland verboten?', '在德国，涉及以色列国家的哪种行为是被禁止的？', '德国严格禁止任何仇恨性言论，包括公开呼吁消灭某一国家或民族。这类行为构成“煽动民 族仇恨”（Volksverhetzung），属于刑事犯罪。', 0, 111, NOW(), NOW()),
  ('bea2923e-81d1-48c4-a6d3-bb81a96c6ed3', '00000000-0000-0000-0000-000000000001', 'Die Wahlen in Deutschland sind …', '德国的选举是……', '德国实行秘密投票制度，确保每位公民在不受影响的情况下自由表达其选举意愿。', 0, 112, NOW(), NOW()),
  ('60a349fa-a404-4085-86df-a85313f2a667', '00000000-0000-0000-0000-000000000001', 'Wahlen in Deutschland gewinnt die Partei, die …', '在德国，赢得选举的是哪一个政党？', '选举中获总票数（尤其是第二选票）最多的政党拥有最多议席，也更有可能组阁成功。', 0, 113, NOW(), NOW()),
  ('e5262117-1966-41b7-ba0e-af233a97f318', '00000000-0000-0000-0000-000000000001', 'An demokratischen Wahlen in Deutschland teilzunehmen ist …', '在德国参加民主选举是……', '德国公民享有选举权，但不是强制投票制度，即参与投票是权利而非义务。', 0, 114, NOW(), NOW()),
  ('323b1d0d-71c7-47de-898d-97ee19e7df63', '00000000-0000-0000-0000-000000000001', 'Was bedeutet "aktives Wahlrecht" in Deutschland?', '在德国，“主动选举权”是什么意思？', '“主动选举权”（aktives Wahlrecht）指的是有权利参与选举、投票的权利，相对于“被动选 举权”（可被选）。', 0, 115, NOW(), NOW()),
  ('e4856e34-fe56-4385-8a42-e363b01acd3d', '00000000-0000-0000-0000-000000000001', 'Wenn Sie bei einer Bundestagswahl in Deutschland wählen dürfen, heißt das …', '如果你可以在德国联邦议院选举中投票，这意味着……', '再次强调，拥有投票权就是拥有“主动选举权”。', 0, 116, NOW(), NOW()),
  ('2edd804b-56ca-4e94-b640-3ca78193aee4', '00000000-0000-0000-0000-000000000001', 'Wie viel Prozent der Zweitstimmen müssen Parteien mindestens bekommen, um in den Deutschen Bun destag gewählt zu werden?', '政党至少要获得多少比例的第二选票，才能进入联邦议院？', '德国联邦议院实行“5%门槛规则”，旨在防止议会过于分散。', 0, 117, NOW(), NOW()),
  ('199ec10b-e044-4549-9762-db5bcd20f106', '00000000-0000-0000-0000-000000000001', 'Wer darf bei den rund 40 jüdischen Makkabi-Sportvereinen Mitglied werden?', '大约40家犹太人马加比体育俱乐部谁可以加入？', '马加比体育协会（Makkabi）虽然具有犹太文化背景，但对所有人开放，体现包容性。', 0, 118, NOW(), NOW()),
  ('21a8e034-b2e3-44d4-8b03-298fb30890a6', '00000000-0000-0000-0000-000000000001', 'Wahlen in Deutschland sind frei. Was bedeutet das?', '德国的选举是自由的。这意味着什么？', '“自由选举”意味着没有强迫、收买或胁迫，投票意愿由个人完全自由决定。', 0, 119, NOW(), NOW()),
  ('154882fc-3e1a-4012-9569-24319188fa74', '00000000-0000-0000-0000-000000000001', 'Das Wahlsystem in Deutschland ist ein …', '德国的选举制度是……', '德国实行混合选举制，结合多数票选（第一选票）与政党比例代表制（第二选票），以实现 公平与代表性。', 0, 120, NOW(), NOW()),
  ('e34626c0-f85b-4096-b257-01d42fb06592', '00000000-0000-0000-0000-000000000001', 'Eine Partei möchte in den Deutschen Bundestag. Sie muss aber einen Mindestanteil an Wählerstimmen h aben. Das heißt …', '一个政党想进入德国联邦议院，但必须获得最低比例的选票。这被称为……', '德国选举制度规定，政党必须在全国范围内获得至少5%的第二选票才能进入联邦议院，这就 是“5%-Hürde”。', 0, 121, NOW(), NOW()),
  ('4ba77905-4860-4375-bcc1-a8e8eed10a0b', '00000000-0000-0000-0000-000000000001', 'Welchem Grundsatz unterliegen Wahlen in Deutschland? Wahlen in Deutschland sind …', '德国选举遵循哪一基本原则？', '《德国基本法》规定选举必须是自由的、平等的、保密的，这是民主国家的核心选举原则。', 0, 122, NOW(), NOW()),
  ('dd3acc43-5864-4969-b84b-35c7f06a58e5', '00000000-0000-0000-0000-000000000001', 'Was ist in Deutschland die "5%-Hürde"?', '在德国，“5%门槛”指的是什么？', '5%门槛是为了防止议会过于碎片化，提高政府稳定性。未达到5%的政党通常不能获得议席。', 0, 123, NOW(), NOW()),
  ('7bd57aee-21c1-42c5-9b65-9fb90ed45c6d', '00000000-0000-0000-0000-000000000001', 'Die Bundestagswahl in Deutschland ist die Wahl …', '德国联邦议院选举是……的选举？', '联邦议院是德国最高立法机关，选民通过选举联邦议员组成议会，而非直接选总理或总统。', 0, 124, NOW(), NOW()),
  ('788f8cba-1614-4783-b4de-1b984dfd0ebc', '00000000-0000-0000-0000-000000000001', 'In einer Demokratie ist eine Funktion von regelmäßigen Wahlen, …', '在民主制度中，定期选举的一个作用是……', '定期选举是民主的核心机制之一，允许通过合法方式实现政权更替，体现民意。', 0, 125, NOW(), NOW()),
  ('5e014bdf-6f08-45e2-be4b-0155587fdd1e', '00000000-0000-0000-0000-000000000001', 'Was bekommen wahlberechtigte Bürgerinnen und Bürger in Deutschland vor einer Wahl?', '德国的合格选民在选举前会收到什么？', '市政办公室会提前邮寄Wahlbenachrichtigung（选举通知），告知选民投票时间、地点等信 息。', 0, 126, NOW(), NOW()),
  ('96789c59-f4e6-48e5-97b8-7fd95c0140d4', '00000000-0000-0000-0000-000000000001', 'Warum gibt es die 5%-Hürde im Wahlgesetz der Bundesrepublik Deutschland? Es gibt sie, weil …', '为什么德国联邦选举法中设有5%门槛？', '设立门槛是为了防止议会过度分裂，保障政府稳定性和效率，避免“悬浮议会”。', 0, 127, NOW(), NOW()),
  ('689ebc0f-7ebf-4245-8aeb-4cf169ba3567', '00000000-0000-0000-0000-000000000001', 'Parlamentsmitglieder, die von den Bürgerinnen und Bürgern gewählt werden, nennt man …', '由公民选出的议会成员被称为什么？', '德国议会成员称为“Abgeordnete（议员）”，直接由选民选出，参与国家立法。', 0, 128, NOW(), NOW()),
  ('8017f3cb-6bc5-4ca5-8e8e-394b23bdf1bb', '00000000-0000-0000-0000-000000000001', 'Vom Volk gewählt wird in Deutschland …', '在德国，由人民直接选举的是……', '德国选民不直接选举总理或总统，而是选出议员组成联邦议院，间接决定总理人选。', 0, 129, NOW(), NOW()),
  ('c5e53a61-8800-44ca-9864-ba14a4e4bd85', '00000000-0000-0000-0000-000000000001', 'Welcher Stimmzettel wäre bei einer Bundestagswahl gültig?', '在联邦议院选举中，哪一张选票是有效的？', '该题涉及选票示意图，通常“1号选票”是填写正确、不违规的示例。有效选票不能有涂改、 两处打勾等错误。只有图1中的选票符合以下要求：德国联邦议院选举的选票上有两栏，选民 拥有“两票”(Sie haben 2 Stimmen) 。一张有效的选票必须清晰地表明选民的意图，通常是在每 一栏中各选择一项。 第一票 (Erststimme): 用于选举您所在选区的直选议员。 第二票 (Zweitstim me): 用于选举一个政党，这决定了各政党在联邦议院中的席位比例。', 0, 130, NOW(), NOW()),
  ('35d6d660-5666-44d0-94a0-e76f0155d772', '00000000-0000-0000-0000-000000000001', 'In Deutschland ist eine Bürgermeisterin/ein Bürgermeister …', '在德国，市长是……', '德国的市长（Bürgermeister/in）是市镇政府的最高领导人，负责行政管理与地方事务。', 0, 131, NOW(), NOW()),
  ('f4374a9d-42bc-46e8-b22a-b4ee9ff2fa9a', '00000000-0000-0000-0000-000000000001', 'Viele Menschen in Deutschland arbeiten in ihrer Freizeit ehrenamtlich. Was bedeutet das?', '许多德国人在空闲时间从事志愿工作，这意味着什么？', '志愿工作（ehrenamtliche Arbeit）是德国社会的重要组成部分，常见于消防、体育、慈善等领 域。', 0, 132, NOW(), NOW()),
  ('e6119d9a-6062-43bb-980c-8529c186ab41', '00000000-0000-0000-0000-000000000001', 'Was ist bei Bundestags- und Landtagswahlen in Deutschland erlaubt?', '在德国联邦议院和州议会选举中，哪项是允许的？', '德国允许邮寄投票（Briefwahl），确保无法亲自前往投票站的选民也能行使投票权。', 0, 133, NOW(), NOW()),
  ('6f40e90b-64c8-445e-ab38-11c9cd4d6697', '00000000-0000-0000-0000-000000000001', 'Man will die Buslinie abschaffen, mit der Sie immer zur Arbeit fahren. Was können Sie machen, um die Buslinie zu erhalten?', '如果要取消您上班时常用的公交线路，您可以怎么做来保留这条线路？', '德国有广泛的市民参与机制，通过“Bürgerinitiative（市民倡议）”可以影响地方政策决策。', 0, 134, NOW(), NOW()),
  ('0f86c1bb-c220-41e3-a56a-954afdf785b3', '00000000-0000-0000-0000-000000000001', 'Wen vertreten die Gewerkschaften in Deutschland?', '德国的工会代表谁的利益？', '工会（Gewerkschaften）在德国主要代表劳动者的权益，尤其在工资谈判和劳动合同方面具有 法律地位。', 0, 135, NOW(), NOW()),
  ('219c6348-c9ca-4a0f-ad1b-e7db3c00a16d', '00000000-0000-0000-0000-000000000001', 'Sie gehen in Deutschland zum Arbeitsgericht bei …', '您在什么情况下会去德国的劳动法院？', '德国设有劳动法院（Arbeitsgericht），处理与雇佣关系相关的纠纷，如解雇、工资、合同 等。', 0, 136, NOW(), NOW()),
  ('ff5e7a61-3d76-46b2-8f82-6d22f77a0fbd', '00000000-0000-0000-0000-000000000001', 'Welches Gericht ist in Deutschland bei Konflikten in der Arbeitswelt zuständig?', '在德国，处理劳动纠纷的法院是哪个？', '德国的劳动法院体系包括初审、上诉和联邦层级，专门处理劳动法律相关事务。', 0, 137, NOW(), NOW()),
  ('00d4ea5c-3fc0-48ee-a110-85f0d163d166', '00000000-0000-0000-0000-000000000001', 'Was kann ich in Deutschland machen, wenn mir meine Arbeitgeberin/mein Arbeitgeber zu Unrecht gek ündigt hat?', '如果雇主无理由解雇我，我在德国可以怎么做？', '德国《解雇保护法》允许被不当解雇的员工在3周内向劳动法院提起诉讼。', 0, 138, NOW(), NOW()),
  ('525fc430-ba45-4ac4-88ca-aac9764337b7', '00000000-0000-0000-0000-000000000001', 'Wann kommt es in Deutschland zu einem Prozess vor Gericht? Wenn jemand …', '在德国，什么时候会进行法庭审判？', '只有在涉嫌**犯罪（Straftat）**并被正式起诉时，才会启动法院程序。表达不同政治观点在德 国是受保护的。', 0, 139, NOW(), NOW()),
  ('b9805176-6298-44c0-a71e-947a98569d11', '00000000-0000-0000-0000-000000000001', 'Was macht eine Schöffin/ein Schöffe in Deutschland? Sie/Er …', '德国的陪审员（Schöffe）负责什么？', '在德国的刑事案件中，Schöffe 是一位没有法律专业背景的志愿陪审员，与职业法官一起参与 案件审理，共同决定被告的有罪与否及量刑，体现了公民参与司法的制度。', 0, 140, NOW(), NOW()),
  ('3a1aa0a8-53d1-4cdc-81ed-cee7b09ba6c9', '00000000-0000-0000-0000-000000000001', 'Wer berät in Deutschland Personen bei Rechtsfragen und vertritt sie vor Gericht?', '在德国，谁负责为人们提供法律咨询并在法庭上代表他们？', '律师（Rechtsanwalt/-anwältin）是专门从事法律咨询并代表客户出庭的专业人员。其他如法 官、陪审员、检察官虽在司法系统内工作，但不代表个人出庭。', 0, 141, NOW(), NOW()),
  ('ad287306-f237-49cb-bf71-fc6d3287fd00', '00000000-0000-0000-0000-000000000001', 'Was ist die Hauptaufgabe einer Richterin/eines Richters in Deutschland?', '在德国，法官的主要职责是什么？', '德国的法官负责依法独立地作出判决，不受政府或其他机关的影响。他们的职责是审理案件 并宣布裁决，而非立法或代表市民。', 0, 142, NOW(), NOW()),
  ('71c67ee2-18c2-498c-9c35-c1e1679aa1d0', '00000000-0000-0000-0000-000000000001', 'Eine Richterin/ein Richter in Deutschland gehört zur …', '德国的法官属于哪个权力部门？', '根据德国的三权分立制度，法官属于Judikative（司法权），与行政权（Exekutive）和立法权 （Legislative）相互独立。', 0, 143, NOW(), NOW()),
  ('c529b5b1-dd25-4129-9b95-3b625dec3916', '00000000-0000-0000-0000-000000000001', 'Eine Richterin/ein Richter gehört in Deutschland zur …', '在德国，法官属于哪种国家权力？', '法官属于rechtsprechende Gewalt（司法权），这是德国宪法所确认的三大国家权力之一，独 立行使审判职权。', 0, 144, NOW(), NOW()),
  ('fd6aac41-5382-4469-b9c4-aefa4a976212', '00000000-0000-0000-0000-000000000001', 'In Deutschland wird die Staatsgewalt geteilt. Für welche Staatsgewalt arbeitet eine Richterin/ein Richter? Für die …', '德国实行三权分立。法官隶属于哪一权力体系？', '法官在德国代表的是Judikative（司法权），即法庭系统，与其他权力机关相互制衡。', 0, 145, NOW(), NOW()),
  ('1db8ce09-caa2-4bdc-9137-4be31ddfc604', '00000000-0000-0000-0000-000000000001', 'Wie nennt man in Deutschland ein Verfahren vor einem Gericht?', '在德国，法院审理案件的程序被称为什么？', '“Prozess”指的是正式的司法程序或诉讼，法院依据法律对案件进行审理。', 0, 146, NOW(), NOW()),
  ('de9dc6e9-063e-48e8-960d-91feaa1c908d', '00000000-0000-0000-0000-000000000001', 'Was ist die Arbeit einer Richterin/eines Richters in Deutschland?', '在德国，法官的工作是什么？', '德国法官的职责是Recht sprechen（司法判决），即依据现行法律对案件作出判决。', 0, 147, NOW(), NOW()),
  ('6a218b67-b5a9-41d1-9676-f64d989eb328', '00000000-0000-0000-0000-000000000001', 'Was ist eine Aufgabe der Polizei in Deutschland?', '在德国，警察的职责是什么？', '德国警察的主要任务是监督法律的遵守，确保社会秩序和公共安全，而非制定法律。', 0, 148, NOW(), NOW()),
  ('b59e807e-07d7-4e36-9b02-f96a251e6e07', '00000000-0000-0000-0000-000000000001', 'Was ist ein Beispiel für antisemitisches Verhalten?', '下列哪项是反犹太主义行为的例子？', '**否认大屠杀（Holocaust）**是严重的反犹太行为，是对历史事实的扭曲，伤害犹太人群体记 忆和尊严，在德国甚至被定为刑事犯罪。', 0, 149, NOW(), NOW()),
  ('1c71015a-53b5-4882-ab93-f26bb8419be2', '00000000-0000-0000-0000-000000000001', 'Eine Gerichtsschöffin/ein Gerichtsschöffe in Deutschland ist …', '在德国，法院的陪审员是……', 'Schöffe 是一种不具备法律学历的志愿法官，代表普通公民参与司法公正，与职业法官一起审 理刑事案件。', 0, 150, NOW(), NOW()),
  ('1dcec52a-5876-4ad1-92a2-0bc7d15f7e13', '00000000-0000-0000-0000-000000000001', 'Wer baute die Mauer in Berlin?', '谁修建了柏林墙？', '柏林墙是东德（DDR）政府于1961年修建的，旨在阻止东德民众逃往西柏林，象征着冷战时 期东西方的对立。', 0, 151, NOW(), NOW()),
  ('c2f006f8-e015-46ce-a924-c04bf86c853f', '00000000-0000-0000-0000-000000000001', 'Wann waren die Nationalsozialisten mit Adolf Hitler in Deutschland an der Macht?', '纳粹党在阿道夫·希特勒领导下在德国掌权的时间是？', '纳粹党于1933年掌权，希特勒成为德国总理，并建立独裁统治，直到1945年二战结束，纳粹 政权倒台。', 0, 152, NOW(), NOW()),
  ('de5a01cb-f939-4847-b055-3cd7c7d979bf', '00000000-0000-0000-0000-000000000001', 'Was war am 8. Mai 1945?', '1945年5月8日发生了什么？', '1945年5月8日是德国在二战中无条件投降的日子，被视为欧洲战争结束日，也称为“胜利 日”。', 0, 153, NOW(), NOW()),
  ('f0bbb73f-0476-4123-9615-191b84af6005', '00000000-0000-0000-0000-000000000001', 'Wann war der Zweite Weltkrieg zu Ende?', '第二次世界大战何时结束？', '第二次世界大战于1945年结束，标志事件为德国5月投降和日本9月投降。', 0, 154, NOW(), NOW()),
  ('b116f384-01ea-4a7a-96dc-63fd511691be', '00000000-0000-0000-0000-000000000001', 'Wann waren die Nationalsozialisten in Deutschland an der Macht?', '纳粹党在德国掌权的时间是？', '这是对前题的重复确认：纳粹统治从1933年希特勒上台到1945年战败为止，共12年。', 0, 155, NOW(), NOW()),
  ('9ae15018-1a27-4c05-a2d0-1c20f5de826a', '00000000-0000-0000-0000-000000000001', 'In welchem Jahr wurde Hitler Reichskanzler?', '希特勒在哪一年成为德国总理（Reichskanzler）？', '阿道夫·希特勒在1933年1月30日被任命为德国总理，随后建立纳粹专政。', 0, 156, NOW(), NOW()),
  ('077d7b92-d653-4066-9d7c-757021c24ade', '00000000-0000-0000-0000-000000000001', 'Die Nationalsozialisten mit Adolf Hitler errichteten 1933 in Deutschland …', '1933年，希特勒领导的纳粹党在德国建立了……', '纳粹党上台后废除民主制度，建立极权主义独裁统治，镇压异己、控制媒体、迫害少数群 体。', 0, 157, NOW(), NOW()),
  ('9566c6ff-db45-4abf-925f-4e2889c76268', '00000000-0000-0000-0000-000000000001', 'Das "Dritte Reich" war eine …', '“第三帝国”（Dritte Reich）是一个……', '“第三帝国”是纳粹党用来称呼其统治时期的术语，是典型的独裁统治国家，没有法治和人 权。', 0, 158, NOW(), NOW()),
  ('d7121e37-c237-4a40-a84f-96acc98e6e39', '00000000-0000-0000-0000-000000000001', 'Was gab es in Deutschland nicht während der Zeit des Nationalsozialismus?', '纳粹统治时期德国缺少什么？', '纳粹上台后，取消多党选举制度和选民自由选择权，实行一党专政，选举名存实亡。', 0, 159, NOW(), NOW()),
  ('dac1e635-e8d6-44f4-95af-d49d6eda0fa3', '00000000-0000-0000-0000-000000000001', 'Welcher Krieg dauerte von 1939 bis 1945?', '哪一场战争从1939年持续到1945年？', '第二次世界大战从1939年德国入侵波兰开始，直到1945年德国与日本战败结束。 是20世纪最 具破坏力的全球性战争。', 0, 160, NOW(), NOW()),
  ('b6067de6-13fc-4504-a82f-c558346f2629', '00000000-0000-0000-0000-000000000001', 'Was kennzeichnete den NS-Staat? Eine Politik …', '纳粹国家的特征是实行什么政策？', '纳粹政权实行极端种族主义政策，主张雅利安人至上，迫害犹太人、罗姆人、残疾人等，完 全剥夺基本人权和自由。', 0, 161, NOW(), NOW()),
  ('3a6d2637-2139-40d0-af31-e153edb16e89', '00000000-0000-0000-0000-000000000001', 'Claus Schenk Graf von Stauffenberg wurde bekannt durch …', '克劳斯·冯·施陶芬贝格伯爵因什么事而闻名？', '施陶芬贝格是德国抵抗运动中的关键人物，在1944年策划了刺杀希特勒的“7·20行动”，但 未成功，最终被处决。', 0, 162, NOW(), NOW()),
  ('e11e4361-d980-46af-84f0-c152a9ca2456', '00000000-0000-0000-0000-000000000001', 'In welchem Jahr zerstörten die Nationalsozialisten Synagogen und jüdische Geschäfte in Deutschland?', '纳粹分子在德国破坏犹太教堂和商店的事件发生在哪一年？', '1938年11月9日至10日，发生了“水晶之夜”（Kristallnacht），这是大规模组织性反犹暴力行 动，全国范围内焚烧犹太教堂、砸毁商店、逮捕犹太人。', 0, 163, NOW(), NOW()),
  ('8b81b051-43bd-4193-89d9-c8663110b84a', '00000000-0000-0000-0000-000000000001', 'Was passierte am 9. November 1938 in Deutschland?', '1938年11月9日，德国发生了什么？', '1938年11月9日是“水晶之夜”，纳粹分子有组织地袭击犹太人财产与宗教场所，标志着犹太 人系统性迫害升级。', 0, 164, NOW(), NOW()),
  ('8d80ca01-8760-4c8b-9c23-734c0bcca598', '00000000-0000-0000-0000-000000000001', 'Wie hieß der erste Bundeskanzler der Bundesrepublik Deutschland?', '联邦德国的第一任总理是谁？', '**康拉德·阿登纳（Konrad Adenauer）**是德国战后第一任联邦总理（任期1949–1963），引 领德国走向西方民主国家行列。', 0, 165, NOW(), NOW()),
  ('eab5c93a-165c-4b37-8954-78cb9ca9563e', '00000000-0000-0000-0000-000000000001', 'Bei welchen Demonstrationen in Deutschland riefen die Menschen "Wir sind das Volk"?', '在德国，民众在哪些示威中喊出了“我们是人民”这句话？', '1989年，东德民众每周一举行和平示威，高呼“Wir sind das Volk!（我们是人民）”，要求自 由和民主，最终促成柏林墙倒塌和德国统一。', 0, 166, NOW(), NOW()),
  ('530fa7e5-d054-42db-87ea-9a9c0b829c1b', '00000000-0000-0000-0000-000000000001', 'Welche Länder wurden nach dem Zweiten Weltkrieg in Deutschland als "Alliierte Besatzungsmächte" be zeichnet?', '二战后，哪些国家被称为德国的“占领盟国”？', '战后德国由四个战胜国分区占领，分别是：美国、苏联、英国和法国，这四国被称为“占领 盟军”。', 0, 167, NOW(), NOW()),
  ('a90f0313-e207-4fd4-bd25-25535e0fc16d', '00000000-0000-0000-0000-000000000001', 'Welches Land war keine "Alliierte Besatzungsmacht" in Deutschland?', '以下哪个国家不是德国的“占领盟国”？', '日本在二战中是轴心国一方的成员，与德国是盟友，不可能成为德国的占领国。', 0, 168, NOW(), NOW()),
  ('6217be91-84f9-4ce8-bbe0-29f30b647708', '00000000-0000-0000-0000-000000000001', 'Wann wurde die Bundesrepublik Deutschland gegründet?', '联邦德国是哪一年成立的？', '1949年5月23日，《基本法》生效，德意志联邦共和国（西德）正式成立，作为战后西方三 国占领区的政权延续。', 0, 169, NOW(), NOW()),
  ('c0709aa4-c90f-44fd-a8b8-4df56c447c0f', '00000000-0000-0000-0000-000000000001', 'Was gab es während der Zeit des Nationalsozialismus in Deutschland?', '在纳粹统治时期，德国存在以下哪种情况？', '纳粹党一党专政，禁止其他政党存在，彻底扼杀民主制度，并取消基本人权与自由。', 0, 170, NOW(), NOW()),
  ('549fc802-dd5a-4820-934e-96acdeffb5c7', '00000000-0000-0000-0000-000000000001', 'Soziale Marktwirtschaft bedeutet, die Wirtschaft …', '“社会市场经济”意味着：经济……', '德国实行的社会市场经济（Soziale Marktwirtschaft）是在自由市场机制下，由国家保障社会 正义和公平的一种制度。国家会干预市场，确保弱势群体得到基本保障。', 0, 171, NOW(), NOW()),
  ('f0b0fbbf-a341-4be5-aa64-c3ae47d712a3', '00000000-0000-0000-0000-000000000001', 'In welcher Besatzungszone wurde die DDR gegründet? In der …', '东德是在哪个占领区成立的？', '1949年10月，德意志民主共和国（DDR）在苏联控制的占领区成立，与西德相对，是冷战期 间社会主义阵营的成员。', 0, 172, NOW(), NOW()),
  ('4f99848e-963e-41a2-9c8a-e4e28e3d27ac', '00000000-0000-0000-0000-000000000001', 'Die Bundesrepublik Deutschland ist ein Gründungsmitglied …', '德国是以下哪个组织的创始成员？', '德国是欧盟的创始成员国，最初是1957年签署《罗马条约》时的“欧洲经济共同体”成员， 后演变为欧盟。', 0, 173, NOW(), NOW()),
  ('952c04e2-8721-401f-978d-1130434d319a', '00000000-0000-0000-0000-000000000001', 'Wann wurde die DDR gegründet?', '东德（德意志民主共和国）是什么时候成立的？', '1949年10月7日，DDR正式成立，作为苏联控制的德国东部政权，与同年5月成立的西德分庭 抗礼。', 0, 174, NOW(), NOW()),
  ('3a170532-b994-4f5e-8a49-27198cf41f0f', '00000000-0000-0000-0000-000000000001', 'Wie viele Besatzungszonen gab es in Deutschland nach dem Zweiten Weltkrieg?', '二战后德国被分为几个占领区？', '战后德国被美国、英国、苏联、法国分为四个占领区，这种安排延续至冷战初期。', 0, 175, NOW(), NOW()),
  ('1233f648-e40a-4156-885a-fc9b4591d0c2', '00000000-0000-0000-0000-000000000001', 'Wie waren die Besatzungszonen Deutschlands nach 1945 verteilt?', '1945年后德国占领区的分配情况是？', '此题是选择正确的代号分配顺序，正确答案为 1=英国、2=苏联、3=美国、4=法国，这是四 国分区管理德国的安排。', 0, 176, NOW(), NOW()),
  ('1f94c70b-0eba-4c08-abcf-1a28ff1eb786', '00000000-0000-0000-0000-000000000001', 'Welche deutsche Stadt wurde nach dem Zweiten Weltkrieg in vier Sektoren aufgeteilt?', '哪座德国城市在二战后被划分为四个区域？', '柏林被四个占领国分别管理，形成东西柏林的对立格局，是冷战象征城市之一。', 0, 177, NOW(), NOW()),
  ('4ad59fd0-97c4-4679-a45f-fc35ad84995b', '00000000-0000-0000-0000-000000000001', 'Vom Juni 1948 bis zum Mai 1949 wurden die Bürgerinnen und Bürger von West-Berlin durch eine Luftb rücke versorgt. Welcher Umstand war dafür verantwortlich?', '1948年6月到1949年5月，西柏林居民通过空运获得补给，其原因是什么？', '1948年，苏联封锁通往西柏林的陆路，盟军通过空运物资（柏林空运）维持西柏林居民生 活，是冷战初期重要事件。', 0, 178, NOW(), NOW()),
  ('1f774c10-bfff-4a4b-8ef9-43ac1002ffb2', '00000000-0000-0000-0000-000000000001', 'Wie endete der Zweite Weltkrieg in Europa offiziell?', '欧洲的第二次世界大战是如何正式结束的？', '德国于1945年5月8日宣布无条件投降，这是欧洲战场正式结束的标志性事件。', 0, 179, NOW(), NOW()),
  ('32031efc-d3da-41e3-9a3a-0b00a1007081', '00000000-0000-0000-0000-000000000001', 'Der erste Bundeskanzler der Bundesrepublik Deutschland war …', '联邦德国的第一任总理是……', '康拉德·阿登纳担任西德首任总理，从1949年至1963年在位，领导德国经济复苏和西方联 盟。', 0, 180, NOW(), NOW()),
  ('8fbeab3a-dbc6-44fc-990b-cdd3e93b01f5', '00000000-0000-0000-0000-000000000001', 'Was wollte Willy Brandt mit seinem Kniefall 1970 im ehemaligen jüdischen Ghetto in Warschau ausdrüc ken?', '维利·勃兰特1970年在华沙犹太人旧居跪下，是想表达什么？', '1970年，德国总理勃兰特在华沙犹太人起义纪念碑前下跪，以此表达对纳粹罪行的忏悔与对 受害者的歉意，成为战后德国对犹太人最具象征意义的道歉行动。', 0, 181, NOW(), NOW()),
  ('fb323a0a-fa52-4b72-b668-a2d0126b1b29', '00000000-0000-0000-0000-000000000001', 'Wie heißt das jüdische Gebetshaus?', '犹太教的礼拜场所叫什么？', '犹太教的信徒在**Synagoge（犹太会堂）**举行宗教仪式，类似于基督教的教堂或伊斯兰教的 清真寺。', 0, 182, NOW(), NOW()),
  ('1bb5eb46-fdf6-4184-b6e7-60a76f59b8d2', '00000000-0000-0000-0000-000000000001', 'Wann war in der Bundesrepublik Deutschland das "Wirtschaftswunder"?', '德国联邦共和国的“经济奇迹”发生在哪个年代？', '二战后德国经历快速重建和经济腾飞，这一时期被称为**“Wirtschaftswunder（经济奇 迹）”，主要发生在1950年代**，得益于马歇尔计划、货币改革和社会市场经济体制。', 0, 183, NOW(), NOW()),
  ('6359f100-a9c4-4b40-a715-297bd0355813', '00000000-0000-0000-0000-000000000001', 'Auf welcher rechtlichen Grundlage wurde der Staat Israel gegründet?', '以色列国家的建立依据哪项法律文件？', '1947年，联合国大会通过第181号决议，决定将巴勒斯坦分为一个犹太国家和一个阿拉伯国 家，为以色列的建立提供了国际法基础。', 0, 184, NOW(), NOW()),
  ('6f9ae754-dd30-4c11-abe8-8f6fa79e446e', '00000000-0000-0000-0000-000000000001', 'Wofür stand der Ausdruck "Eiserner Vorhang"? Für die Abschottung …', '“铁幕”这个说法代表什么？它指的是……', '“铁幕”是指苏联主导的社会主义国家与西方资本主义国家之间的政治和意识形态隔离，尤 其是在冷战期间，东欧被隔离于“铁幕”之后。', 0, 185, NOW(), NOW()),
  ('103caf2a-ff62-4f9e-884f-adff86bf87c5', '00000000-0000-0000-0000-000000000001', 'Im Jahr 1953 gab es in der DDR einen Aufstand, an den lange Zeit in der Bundesrepublik Deutschland e in Feiertag erinnerte. Wann war das?', '1953年东德发生了一场起义，联邦德国长期以哪一天作为纪念日？', '1953年6月17日，东德工人举行起义，要求自由与更好生活条件。西德将6月17日定为“德国 统一日”纪念，直至1990年统一后改为10月3日。', 0, 186, NOW(), NOW()),
  ('3a95b631-3a4a-48fd-8a67-b617474fc442', '00000000-0000-0000-0000-000000000001', 'Welcher deutsche Staat hatte eine schwarz-rot-goldene Flagge mit Hammer, Zirkel und Ährenkranz?', '哪个德国国家的黑红金国旗上带有锤子、圆规和麦穗图案？', '东德（DDR）的国旗在传统黑红金三色上加了象征工农联盟的锤子、圆规和麦穗图案，代 表社会主义国家特征。', 0, 187, NOW(), NOW()),
  ('34bf5b33-7645-42ee-9feb-66cfe3bfd640', '00000000-0000-0000-0000-000000000001', 'In welchem Jahr wurde die Mauer in Berlin gebaut?', '柏林墙是哪一年修建的？', '柏林墙于1961年8月13日修建，是东德政府为防止民众逃往西柏林而建，被视为冷战的象征。', 0, 188, NOW(), NOW()),
  ('f4b043df-e037-4d95-8e32-f28c8a831e02', '00000000-0000-0000-0000-000000000001', 'Wann baute die DDR die Mauer in Berlin?', '东德是哪一年修建柏林墙的？', '与上一题一致，柏林墙是1961年由东德建造，彻底切断东西柏林之间的自由通行。', 0, 189, NOW(), NOW()),
  ('48a70991-ec07-49da-a0ea-70e6fbcd6ecd', '00000000-0000-0000-0000-000000000001', 'Was bedeutet die Abkürzung DDR?', '缩写“DDR”代表什么？', '**DDR 是“Deutsche Demokratische Republik”（德意志民主共和国）**的缩写，指的是1949– 1990年存在的东德政权。', 0, 190, NOW(), NOW()),
  ('5abd4c57-8cb1-40fa-947b-2d93ead35d3b', '00000000-0000-0000-0000-000000000001', 'Wann wurde die Mauer in Berlin für alle geöffnet?', '柏林墙是什么时候向所有人开放的？', '1989年11月9日，东德政府在抗议压力下宣布开放边境，柏林墙随即倒塌，标志着冷战结束和 德国统一的开始。', 0, 191, NOW(), NOW()),
  ('39d8f68e-9662-48ad-8125-74cd9f66d806', '00000000-0000-0000-0000-000000000001', 'Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?', '以下哪个现今的德国联邦州曾属于东德？', '勃兰登堡（Brandenburg）是东德地区的一部分，位于柏林周边，而其他选项皆属西德。', 0, 192, NOW(), NOW()),
  ('e8f909a4-8a7b-41f5-9a4c-e6344fb28f3e', '00000000-0000-0000-0000-000000000001', 'Von 1961 bis 1989 war Berlin …', '1961年至1989年间，柏林的状态是：', '柏林从1961年起被柏林墙分割成东柏林与西柏林，直到1989年墙倒。', 0, 193, NOW(), NOW()),
  ('4e6b5e9d-498b-434c-a0ef-495e82d4ccad', '00000000-0000-0000-0000-000000000001', 'Am 3. Oktober feiert man in Deutschland den Tag der Deutschen …', '每年10月3日，德国庆祝“德国……”纪念日？', '**“德国统一日”（Tag der Deutschen Einheit）**是法定节日，纪念1990年10月3日两德统一。', 0, 194, NOW(), NOW()),
  ('387ff638-da2b-4c4a-93e3-3ab5193b2306', '00000000-0000-0000-0000-000000000001', 'Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?', '以下哪个联邦州曾属于东德？', '萨克森-安哈特（Sachsen-Anhalt）是东德地区之一，1990年后成为统一德国的联邦州。', 0, 195, NOW(), NOW()),
  ('18c37858-0135-46c3-948a-60da4e9d6dd0', '00000000-0000-0000-0000-000000000001', 'Warum nennt man die Zeit im Herbst 1989 in der DDR "Die Wende"? In dieser Zeit veränderte sich die DDR politisch …', '为什么将1989年秋季的东德称为“转折期”（Die Wende）？那时东德发生了怎样的政治变 化？', '“Die Wende（转折）”是指1989年东德和平革命，结束了长达40年的社会主义专制统治，走 向民主与统一。', 0, 196, NOW(), NOW()),
  ('a703d6f8-926a-42cd-a0e2-4b12fbc1b0ed', '00000000-0000-0000-0000-000000000001', 'Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?', '以下哪个德国联邦州曾属于东德？', '**图林根（Thüringen）**位于东德地区，是德国统一后的五个新联邦州之一。', 0, 197, NOW(), NOW()),
  ('57a895f3-405d-4359-93fd-1fb5b476ccfc', '00000000-0000-0000-0000-000000000001', 'Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?', '以下哪个联邦州曾属于东德？', '萨克森（Sachsen）是东德的重要工业州，包括城市如莱比锡和德累斯顿。', 0, 198, NOW(), NOW()),
  ('71cf5cee-c198-4a8f-bf6e-2bbdb94ab7e6', '00000000-0000-0000-0000-000000000001', 'Mit der Abkürzung "Stasi" meinte man in der DDR …', '在东德，“Stasi”是指什么？', 'Stasi 是“国家安全部（Staatssicherheit）”的缩写，是东德的情报机构，以监控公民和压制异 议闻名。', 0, 199, NOW(), NOW()),
  ('7e7dd978-b987-4e49-b847-6c5cbd4994f1', '00000000-0000-0000-0000-000000000001', 'Welches heutige deutsche Bundesland gehörte früher zum Gebiet der DDR?', '以下哪个德国联邦州曾属于东德？', '梅克伦堡-前波美拉尼亚州位于德国东北部，是东德五个新州之一，1990年重建州政府并加入 联邦德国。', 0, 200, NOW(), NOW()),
  ('b5e7d1f3-edd5-44aa-a6ce-e94f5de06e72', '00000000-0000-0000-0000-000000000001', 'Welche der folgenden Auflistungen enthält nur Bundesländer, die zum Gebiet der früheren DDR gehört en?', '以下哪一组仅包含原东德地区的联邦州？', '正确答案中五个州都曾属于东德，其余选项中混入了原西德地区州名（如黑森、巴伐利亚 等）。', 0, 201, NOW(), NOW()),
  ('ecfd0142-cc3f-4d1a-b894-8c3b0e33519d', '00000000-0000-0000-0000-000000000001', 'Zu wem gehörte die DDR im "Kalten Krieg"?', '在“冷战”时期，东德属于哪个阵营？', '东德是苏联主导的华沙条约组织成员，属于社会主义阵营，对立于西德所在的北约阵营。', 0, 202, NOW(), NOW()),
  ('0cb16f6e-2a17-470f-8ada-8a2a4b278745', '00000000-0000-0000-0000-000000000001', 'Wie hieß das Wirtschaftssystem der DDR?', '东德实行的经济制度叫什么？', '东德实行由国家全面调控资源配置的计划经济体制（Planwirtschaft），不遵循市场供需原 则。', 0, 203, NOW(), NOW()),
  ('2704b946-e123-4a33-8d21-bcb971eeaf45', '00000000-0000-0000-0000-000000000001', 'Wie wurden die Bundesrepublik Deutschland und die DDR zu einem Staat?', '联邦德国与东德是如何合并为一个国家的？', '根据《两德统一条约》，1990年东德的五个州依照**《基本法》第23条**，作为联邦州加入 西德，完成统一。', 0, 204, NOW(), NOW()),
  ('2f29948a-8465-40f2-bfe1-01b44178e70d', '00000000-0000-0000-0000-000000000001', 'Mit dem Beitritt der DDR zur Bundesrepublik Deutschland gehören die neuen Bundesländer nun auc h …', '随着东德加入联邦德国，新联邦州也成为……的成员：', '东德并入联邦德国后，其地区也自动**成为欧盟成员（当时为欧洲共同体）**的一部分。', 0, 205, NOW(), NOW()),
  ('46e6aa81-ad76-4e8b-b45f-df3b8ba778bb', '00000000-0000-0000-0000-000000000001', 'Woran erinnern die sogenannten „Stolpersteine“ in Deutschland?', '在德国，“绊脚石（Stolpersteine）”是为了纪念什么？', '“Stolpersteine（绊脚石）”是欧洲最大规模的分布式纪念项目，每块砖代表一位被纳粹迫害 或杀害的个体，通常安放在其最后自由住所前。', 0, 206, NOW(), NOW()),
  ('698f2645-6770-459b-8afc-2c58aa4c6b98', '00000000-0000-0000-0000-000000000001', 'In welchem Militärbündnis war die DDR Mitglied?', '东德曾是哪个军事联盟的成员？', '华沙条约组织是苏联为对抗北约而建立的军事联盟，东德自1955年加入直到统一前一直是成 员国。', 0, 207, NOW(), NOW()),
  ('95d62de3-5a78-4b38-a284-9ad37e521dfd', '00000000-0000-0000-0000-000000000001', 'Was war die "Stasi"?', '“Stasi”指的是什么？', '“Stasi”是东德国家安全部（Staatssicherheit）的简称，是世界上最有效率但也最压迫性的秘 密警察组织之一，监视并控制社会各层面。', 0, 208, NOW(), NOW()),
  ('dd986094-a9f9-4591-a653-bf57267ad106', '00000000-0000-0000-0000-000000000001', 'Welches war das Wappen der Deutschen Demokratischen Republik? （题目中包含图示）', '下列哪个是德意志民主共和国（DDR）的国徽？', 'DDR的国徽包含锤子（工人）、圆规（知识分子）和麦穗（农民），象征社会主义的三大阶 层。', 1, 209, NOW(), NOW()),
  ('d120ffa9-3e45-4844-98de-28f3514b1e97', '00000000-0000-0000-0000-000000000001', 'Was ereignete sich am 17. Juni 1953 in der DDR?', '1953年6月17日，东德发生了什么？', '1953年6月17日，东德爆发了大规模工人罢工和抗议活动，要求改善经济条件与政治自由。 被苏联出动军队镇压，西德将此日定为“德国统一纪念日”。', 0, 210, NOW(), NOW()),
  ('54892d22-4771-4d81-8a6b-8e7bfc2a5a64', '00000000-0000-0000-0000-000000000001', 'Welcher Politiker steht für die "Ostverträge"?', '哪位政治家代表“东方条约”？', '“东方条约”是20世纪70年代初德国与东欧国家签订的一系列条约，旨在缓和冷战时期的紧 张关系。这些条约主要由当时的联邦总理维利·勃兰特（Willy Brandt）推动，他因此获得诺贝 尔和平奖。', 0, 211, NOW(), NOW()),
  ('bf7f9fda-3418-4a5c-9dde-726ddc9ad8cb', '00000000-0000-0000-0000-000000000001', 'Wie heißt Deutschland mit vollem Namen?', '德国的全名是什么？', '德国的官方全称是「德意志联邦共和国」（Bundesrepublik Deutschland），这是德国作为一个 联邦制国家的正式称谓。', 0, 212, NOW(), NOW()),
  ('570628fe-b157-41e6-8828-3c74075600db', '00000000-0000-0000-0000-000000000001', 'Wie viele Einwohner hat Deutschland?', '德国的人口有多少？', '截至2024年，德国人口约为8400万，是欧盟中人口最多的国家。', 0, 213, NOW(), NOW()),
  ('4d98ef0d-6b13-4267-9ecc-3a7fe55d2b3b', '00000000-0000-0000-0000-000000000001', 'Welche Farben hat die deutsche Flagge?', '德国国旗的颜色是什么？', '德国国旗由三种颜色组成，从上至下依次为黑色、红色和金色（schwarz-rot-gold），象征自 由、团结和正义。', 0, 214, NOW(), NOW()),
  ('c19752f3-ebce-48cb-9b60-82b5e5f9b05c', '00000000-0000-0000-0000-000000000001', 'Wer wird als "Kanzler der Deutschen Einheit" bezeichnet?', '谁被称为“德国统一的总理”？', '赫尔穆特·科尔（Helmut Kohl）是德国统一时期的总理，他在东西德合并过程中起了决定性 作用，被称为“统一总理”。', 0, 215, NOW(), NOW()),
  ('652d4636-2f71-4587-8676-8e00baa068ef', '00000000-0000-0000-0000-000000000001', 'Welches Symbol ist im Plenarsaal des Deutschen Bundestages zu sehen?', '德国联邦议会大厅中可以看到什么标志？', '德国联邦议会大厅正面悬挂的是德国的国徽——联邦鹰（Bundesadler），象征国家权力与主 权。', 0, 216, NOW(), NOW()),
  ('272aaf3e-efdf-481b-8b51-a0f7044b0210', '00000000-0000-0000-0000-000000000001', 'In welchem Zeitraum gab es die Deutsche Demokratische Republik (DDR)?', '德意志民主共和国（东德）存在于哪个时期？', '东德（DDR）成立于1949年，在1990年德国统一时并入联邦德国，结束其存在。', 0, 217, NOW(), NOW()),
  ('27e1ad87-b587-4af3-ba70-209f122a4ca8', '00000000-0000-0000-0000-000000000001', 'Wie viele Bundesländer kamen bei der Wiedervereinigung 1990 zur Bundesrepublik Deutschlan d hinzu?', '1990年德国统一时，有多少个联邦州加入了德意志联邦共和国？', '统一时，东德的5个州——勃兰登堡、梅克伦堡-前波美拉尼亚、萨克森、萨克森-安哈尔特和 图林根——重新成立并加入联邦德国。', 0, 218, NOW(), NOW()),
  ('cfb511cd-0952-4b6a-b503-33debcc117bb', '00000000-0000-0000-0000-000000000001', 'Die Bundesrepublik Deutschland hat die Grenzen von heute seit …', '德意志联邦共和国现今的边界从哪一年开始确立？', '随着1990年德国统一以及波兰边界的正式承认，德国的现行边界自1990年起确定。', 0, 219, NOW(), NOW()),
  ('5326a30f-e8a0-4b0b-a8ee-f885826aa2bb', '00000000-0000-0000-0000-000000000001', 'Der 27. Januar ist in Deutschland ein offizieller Gedenktag. Woran erinnert dieser Tag?', '1月27日是德国的官方纪念日，这一天是为了纪念什么？', '1月27日是奥斯维辛集中营被苏联军队解放的日子。德国将这一天定为“纳粹受害者纪念 日”，缅怀大屠杀的受害者。', 0, 220, NOW(), NOW()),
  ('c4c9f6ed-4ce3-4bd9-a66f-f9c925552d1c', '00000000-0000-0000-0000-000000000001', 'Deutschland ist Mitglied des Schengener Abkommens. Was bedeutet das?', '德国是申根协定的成员国。这意味着什么？', '申根协定允许成员国间边境自由流动，大多数欧洲国家之间无需护照检查。该协定并不等同 于全球通行，也不与欧元流通直接相关。', 0, 221, NOW(), NOW()),
  ('5b4ccd16-abc0-4f9d-98ad-374b371f63d0', '00000000-0000-0000-0000-000000000001', 'Welches Land ist ein Nachbarland von Deutschland?', '以下哪个国家是德国的邻国？', '德国与9个国家接壤，其中包括瑞士，而匈牙利、葡萄牙和西班牙并不与德国接壤。', 0, 222, NOW(), NOW()),
  ('5b24532d-0702-43b5-93be-da95eca2f582', '00000000-0000-0000-0000-000000000001', 'Welches Land ist ein Nachbarland von Deutschland?', '以下哪个国家是德国的邻国？', '波兰与德国接壤，是其东部邻国。其他选项均不与德国接壤。', 0, 223, NOW(), NOW()),
  ('87e6583f-7b13-4613-b892-0db0930b8859', '00000000-0000-0000-0000-000000000001', 'Was bedeutet die Abkürzung EU?', 'EU 是什么的缩写？', 'EU 是 „Europäische Union“（欧洲联盟）的缩写，是欧洲多国组成的政治和经济联盟。', 0, 224, NOW(), NOW()),
  ('c9e22392-3acd-42c8-847d-32216c853bc3', '00000000-0000-0000-0000-000000000001', 'In welchem anderen Land gibt es eine große deutschsprachige Bevölkerung?', '在哪个国家有大量讲德语的人口？', '奥地利是德语国家，其官方语言就是德语，几乎全民讲德语。', 0, 225, NOW(), NOW()),
  ('c0dbc95e-9a7f-45a5-8d05-66460d97ea55', '00000000-0000-0000-0000-000000000001', 'Welche ist die Flagge der Europäischen Union?', '哪一面是欧盟的旗帜？', '欧盟的旗帜是蓝底配12颗金色五角星组成的圆环，象征团结、和谐与完整。通常是图3。', 1, 226, NOW(), NOW()),
  ('bc868cb9-8e77-4801-bd2a-a18b5d1817fc', '00000000-0000-0000-0000-000000000001', 'Welches Land ist ein Nachbarland von Deutschland?', '以下哪个国家是德国的邻国？', '丹麦是德国北部邻国，通过一段陆地相连，其余三个国家都与德国不接壤。', 0, 227, NOW(), NOW()),
  ('57ad2d79-9a4d-46fd-a479-49da8295b5fe', '00000000-0000-0000-0000-000000000001', 'Wie wird der Beitritt der DDR zur Bundesrepublik Deutschland im Jahr 1990 allgemein genann t?', '1990年，东德加入联邦德国，这一事件通常被称为？', '1990年东德并入西德，是“德国统一”（Deutsche Wiedervereinigung）的核心事件，标志着冷 战格局在德国的结束。', 0, 228, NOW(), NOW()),
  ('ef9612bc-8a84-4330-9f4c-50347972c82b', '00000000-0000-0000-0000-000000000001', 'Welches Land ist ein Nachbarland von Deutschland?', '以下哪个国家是德国的邻国？', '卢森堡是德国的西部邻国，与德国、法国、比利时接壤。', 0, 229, NOW(), NOW()),
  ('fd597139-098b-444a-a2eb-491874a75e75', '00000000-0000-0000-0000-000000000001', 'Das Europäische Parlament wird regelmäßig gewählt, nämlich alle …', '欧洲议会定期举行选举，其周期是每…', '欧洲议会成员的任期为五年，因此欧洲议会每五年选举一次。', 0, 230, NOW(), NOW()),
  ('667731b5-c708-4b17-9303-540880b90b43', '00000000-0000-0000-0000-000000000001', 'Was bedeutet der Begriff "europäische Integration"?', '“欧洲一体化”这个概念是什么意思？', '“欧洲一体化”是指各欧洲国家在政治、经济等方面日益融合的过程，最终形成了欧盟（E U）这一超国家组织。', 0, 231, NOW(), NOW()),
  ('e284e1c0-9f6f-4064-b49e-c357e1fb576e', '00000000-0000-0000-0000-000000000001', 'Wer wird bei der Europawahl gewählt?', '欧洲议会选举时选的是谁？', '在欧洲议会选举中，欧盟各成员国的公民直接选出代表本国的欧洲议会议员。', 0, 232, NOW(), NOW()),
  ('454be3f7-fbce-4f70-b7e0-dac1ade996ec', '00000000-0000-0000-0000-000000000001', 'Welches Land ist ein Nachbarland von Deutschland?', '以下哪个国家是德国的邻国？', '捷克位于德国东南方向，与德国接壤。其余国家与德国无陆地边界。', 0, 233, NOW(), NOW()),
  ('9b173a14-93b7-4a8a-8742-26e668ec1c54', '00000000-0000-0000-0000-000000000001', 'Wo ist ein Sitz des Europäischen Parlaments?', '欧洲议会在哪个城市设有一个议会所在地？', '欧洲议会的主要会议地点设在法国的斯特拉斯堡（Straßburg），其他办公地还包括布鲁塞尔和 卢森堡。', 0, 234, NOW(), NOW()),
  ('5a3ac206-8458-4a58-8847-18015f4e88ea', '00000000-0000-0000-0000-000000000001', 'Der damalige französische Staatspräsident François Mitterrand und der damalige deutsche Bun deskanzler Helmut Kohl gedenken in Verdun gemeinsam der Toten beider Weltkriege. Welches Ziel der Europäischen Union wird bei diesem Treffen deutlich?', '法国总统密特朗与德国总理科尔在凡尔登共同悼念两次世界大战的死难者。这次会晤体现了 欧盟的哪一目标？', '这一历史性事件象征着法德之间和解，体现出欧盟追求成员国间“和平与安全”的核心目 标。', 0, 235, NOW(), NOW()),
  ('46cf3c9d-784a-4c5c-b26c-58d39f78e77a', '00000000-0000-0000-0000-000000000001', 'Wie viele Mitgliedstaaten hat die EU heute?', '目前欧盟有多少个成员国？', '截至2025年，欧盟共有27个成员国，自2020年英国脱欧后，从28个减少为27个。', 0, 236, NOW(), NOW()),
  ('0b83a735-2880-45e1-8835-87bb158760bd', '00000000-0000-0000-0000-000000000001', '2007 wurde das 50-jährige Jubiläum der "Römischen Verträge" gefeiert. Was war der Inhalt der Verträge?', '2007年是《罗马条约》签署50周年纪念。《罗马条约》的内容是什么？', '《罗马条约》于1957年签署，奠定了欧洲经济共同体（EWG）的基础，是欧盟的前身。', 0, 237, NOW(), NOW()),
  ('19747eb9-d014-42bc-8d38-8be3d37e0fe0', '00000000-0000-0000-0000-000000000001', 'An welchen Orten arbeitet das Europäische Parlament?', '欧洲议会在哪些城市开展工作？', '欧洲议会的主要工作地包括法国的斯特拉斯堡（正式会议）、比利时的布鲁塞尔（委员会会 议）和卢森堡（秘书处）。', 0, 238, NOW(), NOW()),
  ('688187c3-69fd-47ca-8d9e-15746ff53ba8', '00000000-0000-0000-0000-000000000001', 'Durch welche Verträge schloss sich die Bundesrepublik Deutschland mit anderen Staaten zur E uropäischen Wirtschaftsgemeinschaft zusammen?', '德国是通过哪一条约与其他国家联合组成欧洲经济共同体的？', '《罗马条约》签署于1957年，是欧盟建立的重要基础，建立了欧洲经济共同体（EWG）。', 0, 239, NOW(), NOW()),
  ('a7d1cb18-19af-4293-bbd1-1bd5cbdfa01b', '00000000-0000-0000-0000-000000000001', 'Seit wann bezahlt man in Deutschland mit dem Euro in bar?', '从哪一年起，德国开始以现金形式使用欧元？', '欧元纸币和硬币于2002年1月1日正式在德国和其他欧元区国家流通，替代原来的德国马克。', 0, 240, NOW(), NOW()),
  ('45af7fb6-9c24-4f66-ae62-b363f079cc12', '00000000-0000-0000-0000-000000000001', 'Frau Seger bekommt ein Kind. Was muss sie tun, um Elterngeld zu erhalten?', 'Seger女士要生孩子。她要怎样做才能领取育儿津贴（Elterngeld）？', '在德国，想要领取Elterngeld必须主动向负责机构（通常是所在地区的Elterngeldstelle）提出书 面申请，不会自动发放。', 0, 241, NOW(), NOW()),
  ('9872047a-14fd-4bf3-ae08-d31ba0b6cfa6', '00000000-0000-0000-0000-000000000001', 'Wer entscheidet, ob ein Kind in Deutschland in den Kindergarten geht?', '在德国，谁决定孩子是否上幼儿园？', '上幼儿园在德国不是义务教育，由家长决定是否让孩子就读。', 0, 242, NOW(), NOW()),
  ('79fb2fad-10a5-4a73-bb81-05b82d10f1a4', '00000000-0000-0000-0000-000000000001', 'Maik und Sybille wollen mit Freunden an ihrem deutschen Wohnort eine Demonstration auf de r Straße abhalten. Was müssen sie vorher tun?', 'Maik 和 Sybille 想和朋友在他们的德国居住地举行一场街头示威。他们事先必须做什么？', '在德国，示威属于《基本法》保障的自由权利，但需要提前向当地警察机关报备（Anmeldun g）。', 0, 243, NOW(), NOW()),
  ('e144bba6-eaba-4b00-9ce5-4903ba4f28cc', '00000000-0000-0000-0000-000000000001', 'Welchen Schulabschluss braucht man normalerweise, um an einer Universität in Deutschland ei n Studium zu beginnen?', '在德国，通常需要什么学历才能上大学？', 'Abitur 是德国普通高中毕业文凭，通常是大学入学的基本资格。', 0, 244, NOW(), NOW()),
