  ('ebb7ddea-6724-4b70-a330-3b53950a0525', '00000000-0000-0000-0000-000000000001', 'Was ist in Deutschland ein Brauch zu Ostern?', '德国复活节的一个传统是什么？', '在德国，复活节的传统习俗包括彩绘鸡蛋和寻找复活节彩蛋，象征新生与希望。', 0, 293, NOW(), NOW()),
  ('433a8a5c-8b2e-40d9-9749-fd936649eae1', '00000000-0000-0000-0000-000000000001', 'Pfingsten ist ein …', '圣灵降临节（Pfingsten）是一个……', 'Pfingsten 是基督教的重要节日，庆祝圣灵降临到门徒身上，通常在复活节后第七周日和周 一。', 0, 294, NOW(), NOW()),
  ('029f7a5d-26ad-4bd2-891b-e0891fb19387', '00000000-0000-0000-0000-000000000001', 'Welche Religion hat die europäische und deutsche Kultur geprägt?', '哪种宗教对欧洲和德国文化产生了深远影响？', '基督教在历史、法律、教育和节日方面深刻影响了德国和整个欧洲文化传统。', 0, 295, NOW(), NOW()),
  ('b146820a-659b-4865-b21f-60fd0e67b89b', '00000000-0000-0000-0000-000000000001', 'In Deutschland nennt man die letzten vier Wochen vor Weihnachten …', '在德国，圣诞节前的四周被称为……', 'Adventszeit 是圣诞节前四周的等待与准备时期，德国人常点燃降临节蜡烛和布置圣诞装饰。', 0, 296, NOW(), NOW()),
  ('bf45e56c-0147-43da-86b4-26b7a3086df4', '00000000-0000-0000-0000-000000000001', 'Aus welchem Land sind die meisten Migrantinnen und Migranten nach Deutschland gekomme n?', '从哪个国家来德国的移民最多？', '20世纪60年代起，大量土耳其“客籍工人”（Gastarbeiter）被德国引进，形成最大的移民群体 之一。', 0, 297, NOW(), NOW()),
  ('74d76249-8463-42ac-9db4-144c6a79244b', '00000000-0000-0000-0000-000000000001', 'In der DDR lebten vor allem Migrantinnen und Migranten aus …', '在东德（DDR）主要居住着来自哪些国家的移民？', 'DDR 曾与越南、莫桑比克等社会主义国家签订协议，接收其公民作为“合同工”或留学生。', 0, 298, NOW(), NOW()),
  ('e26577ab-9fd9-4f3d-a58e-bae65fe40c4e', '00000000-0000-0000-0000-000000000001', 'Ausländische Arbeitnehmerinnen und Arbeitnehmer, die in den 50er und 60er Jahren von der B undesrepublik Deutschland angeworben wurden, nannte man …', '20世纪50至60年代，德国招募的外国工人被称为……', '为了经济重建，德国在战后与多国签署协议，引进所谓 Gastarbeiter，主要从意大利、土耳 其、希腊等国来德工作。', 0, 299, NOW(), NOW()),
  ('800c4fbc-221c-4923-b8ea-57f1233eb529', '00000000-0000-0000-0000-000000000001', 'Aus welchem Land kamen die ersten Gastarbeiterinnen und Gastarbeiter in die Bundesrepublik Deutschland?', '第一批被引入联邦德国的客籍工人来自哪个国家？', '1955年，德国与意大利签署第一个劳工引进协议，意大利成为第一个派遣客籍工人的国家。', 0, 300, NOW(), NOW()),
  ('7d6244f3-f7f5-46ee-baf9-a5d6e15003b0', '5465e833-302f-4de6-9ca4-c082919dfa68', 'Welches Wappen gehört zum Bundesland Baden-Württemberg?', '哪个州徽属于巴登-符腾堡州？', '巴登-符腾堡州的州徽（大州徽）是金色盾牌上的三只迈步的黑狮，舌头为红色。 这三 只狮子象征着历史上的施瓦本公国。', 1, 0, NOW(), NOW()),
  ('d5a433ac-c8f0-4de2-a5b4-a81cdf9ea65a', '5465e833-302f-4de6-9ca4-c082919dfa68', 'Welches ist ein Landkreis in Baden-Württemberg?', '哪个是巴登-符腾堡州的一个县？', '内卡-奥登瓦尔德县是巴登-符腾堡州北部的一个县。其他选项分别属于：梅克伦堡湖区县（梅前 州）、北弗里斯兰县（石荷州）和阿尔多廷县（巴伐利亚州）。', 0, 1, NOW(), NOW()),
  ('8d35568f-b849-43e2-96a2-e29613e58eff', '5465e833-302f-4de6-9ca4-c082919dfa68', 'Für wie viele Jahre wird der Landtag in Baden-Württemberg gewählt?', '巴登-符腾堡州的州议会每隔多少年选举一次？', '根据德国各州的选举法，巴登-符腾堡州州议会的立法周期为5年。', 0, 2, NOW(), NOW()),
  ('525a1fc4-d035-4e8d-84a8-f01a86617e74', '5465e833-302f-4de6-9ca4-c082919dfa68', 'Ab welchem Alter darf man in Baden-Württemberg bei Kommunalwahlen wählen?', '在巴登-符腾堡州，年满多少岁可以参加地方选举？', '在巴登-符腾堡州，参加市、镇、县等地方选举的最低年龄是16岁。', 0, 3, NOW(), NOW()),
  ('73733f56-78cf-4066-8e0e-1e01b518c421', '5465e833-302f-4de6-9ca4-c082919dfa68', 'Welche Farben hat die Landesflagge von Baden-Württemberg?', '巴登-符腾堡州的州旗是什么颜色的？', '巴登-符腾堡州的州旗由上黑下金（黄）两条水平色带组成，颜色源自其州徽的颜色。', 0, 4, NOW(), NOW()),
  ('08b85202-b4ae-4796-b1cc-961e67b29f97', '5465e833-302f-4de6-9ca4-c082919dfa68', 'Wo können Sie sich in Baden-Württemberg über politische Themen informieren?', '在巴登-符腾堡州，您可以从哪里获取政治主题的信息？', '州政治教育中心(Landeszentrale für politische Bildung)是德国各州设立的官方机构， 旨在提供中立的政治信息和教育，促进公民的政治参与。', 0, 5, NOW(), NOW()),
  ('0ed2c7ad-f73e-46df-bcc8-b19ceab85f51', '5465e833-302f-4de6-9ca4-c082919dfa68', 'Die Landeshauptstadt von Baden-Württemberg heißt...', '巴登-符腾堡州的首府是...', '斯图加特是巴登-符腾堡州的州首府和最大城市。', 0, 6, NOW(), NOW()),
  ('8b4a0c42-e978-4575-990d-5da74f9a2b92', '5465e833-302f-4de6-9ca4-c082919dfa68', 'Welches Bundesland ist Baden-Württemberg?', '哪个联邦州是巴登-符腾堡州？', '地图上数字2指向的区域是德国西南部的巴登-符腾堡州。', 0, 7, NOW(), NOW()),
  ('7bc971c1-1274-4632-81b0-461a8663f21b', '5465e833-302f-4de6-9ca4-c082919dfa68', 'Wie nennt man die Regierungschefin/den Regierungschef in Baden-Württemberg?', '巴登-符腾堡州的政府首脑被称为什么？', '在德国大多数非城市州，政府首脑的官方头衔是“Ministerpräsident(in)”，即州长。', 0, 8, NOW(), NOW()),
  ('dabe8160-8299-4c46-945f-d987e4aacf1a', '5465e833-302f-4de6-9ca4-c082919dfa68', 'Welche Ministerin/welchen Minister hat Baden-Württemberg nicht?', '巴登-符腾堡州没有哪位部长？', '根据《德国基本法》，外交事务属于联邦政府的专属管辖范围，因此各联邦州不设立外 交部或外交部长。', 0, 9, NOW(), NOW()),
  ('4f18f436-42c1-4c27-9405-96417a53f855', '7ec2a519-f626-41fb-a659-d806685f0dd0', 'Welches Wappen gehört zum Freistaat Bayern?', '哪个州徽属于巴伐利亚自由州？', '巴伐利亚州的州徽（小州徽）由蓝白相间的菱形格子图案构成，顶部有“人民皇冠” (Volkskrone)。 这是维特尔斯巴赫家族的传统纹章。', 1, 0, NOW(), NOW()),
