  ('f48c184e-ccd4-40f9-8fda-040f6008b07f', 'f0afa396-bd3b-4d7a-808b-192389673f3d', 'Welches Wappen gehört zum Bundesland Sachsen-Anhalt?', '哪个州徽属于萨克森-安哈尔特州？', '萨克森-安哈尔特的州徽分为上下两部分。上半部分代表萨克森地区，是在黑金条纹上 加绿色菱形花冠，以及一只黑鹰；下半部分代表安哈尔特地区，是一只在红色城墙上行走的黑熊。', 1, 0, NOW(), NOW()),
  ('84df9ee0-f325-4e93-9dc1-82a50d76d1a9', 'f0afa396-bd3b-4d7a-808b-192389673f3d', 'Welches ist ein Landkreis in Sachsen-Anhalt?', '哪个是萨克森-安哈尔特州的一个县？', '博尔德县是萨克森-安哈尔特州的一个县。 其他选项分别属于：阿默尔兰县（下萨克森 州）、阿尔多廷县（巴伐利亚州）和乌克马克县（勃兰登堡州）。', 0, 1, NOW(), NOW()),
  ('084adba1-1afd-4ac9-887f-e933545d4a5a', 'f0afa396-bd3b-4d7a-808b-192389673f3d', 'Für wie viele Jahre wird der Landtag in Sachsen-Anhalt gewählt?', '萨克森-安哈尔特州的州议会每隔多少年选举一次？', '萨克森-安哈尔特州州议会的立法周期为5年。', 0, 2, NOW(), NOW()),
  ('775a0b06-8afc-460d-aefb-a22952f6740c', 'f0afa396-bd3b-4d7a-808b-192389673f3d', 'Ab welchem Alter darf man in Sachsen-Anhalt bei Kommunalwahlen wählen?', '在萨克森-安哈尔特州，年满多少岁可以参加地方选举？', '在萨克森-安哈尔特州，参加地方选举的最低年龄是16岁。', 0, 3, NOW(), NOW()),
  ('1cd1bc51-882d-4f0d-a286-3250dff86c13', 'f0afa396-bd3b-4d7a-808b-192389673f3d', 'Welche Farben hat die Landesflagge von Sachsen-Anhalt?', '萨克森-安哈尔特州的州旗是什么颜色的？', '萨克森-安哈尔特州的州旗由上黄下黑两条水平色带组成，颜色源自其州徽中萨克森 部分的颜色。', 0, 4, NOW(), NOW()),
  ('04532848-9a99-45f5-9101-88f122920f8f', 'f0afa396-bd3b-4d7a-808b-192389673f3d', 'Wo können Sie sich in Sachsen-Anhalt über politische Themen informieren?', '在萨克森-安哈尔特州，您可以从哪里获取政治主题的信息？', '州政治教育中心是获取中立、可靠政治信息的官方机构。', 0, 5, NOW(), NOW()),
  ('02b80da3-bebb-45e2-bb89-1b0cf0daf588', 'f0afa396-bd3b-4d7a-808b-192389673f3d', 'Die Landeshauptstadt von Sachsen-Anhalt heißt...', '萨克森-安哈尔特州的首府是...', '马格德堡是萨克森-安哈尔特州的州首府。', 0, 6, NOW(), NOW()),
  ('e5be80ea-89d0-414d-b6ef-cda61ca31570', 'f0afa396-bd3b-4d7a-808b-192389673f3d', 'Welches Bundesland ist Sachsen-Anhalt?', '哪个联邦州是萨克森-安哈尔特州？', '地图上数字3指向的区域是位于德国中部的萨克森-安哈尔特州。', 0, 7, NOW(), NOW()),
  ('ae6a3432-aa07-44a7-9536-018dcd9cf5ef', 'f0afa396-bd3b-4d7a-808b-192389673f3d', 'Wie nennt man die Regierungschefin/den Regierungschef in Sachsen-Anhalt?', '萨克森-安哈尔特州的政府首脑被称为什么？', '萨克森-安哈尔特州的政府首脑被称为“Ministerpräsident(in)”，即州长。', 0, 8, NOW(), NOW()),
  ('c47e7e6d-1141-429d-aed4-53b0fc7ad793', 'f0afa396-bd3b-4d7a-808b-192389673f3d', 'Welche Ministerin/welchen Minister hat Sachsen-Anhalt nicht?', '萨克森-安哈尔特州没有哪位部长？', '德国联邦州政府层面不设外交部长，此为联邦政府专属职权。', 0, 9, NOW(), NOW()),
  ('39d1c533-4357-4491-b2ab-ed0d09507a36', 'b09aebcc-af92-4eb4-930f-261e53c5ed0d', 'Welches Wappen gehört zum Bundesland Schleswig-Holstein?', '哪个州徽属于石勒苏益格-荷尔斯泰因州？', '石勒苏益格-荷尔斯泰因州的州徽是垂直分开的：左侧黄色背景上有两只蓝色的狮子， 代表石勒苏益格公国；右侧红色背景上是白色荨麻叶，代表荷尔斯泰因公国。', 1, 0, NOW(), NOW()),
  ('a9309877-2231-4f4f-b10d-80e75ba70ad7', 'b09aebcc-af92-4eb4-930f-261e53c5ed0d', 'Welches ist ein Landkreis in Schleswig-Holstein?', '哪个是石勒苏益格-荷尔斯泰因州的一个县？', '北弗里斯兰县是石勒苏益格-荷尔斯泰因州最西北的县，濒临北海。其他选项分别属于 ：阿默尔兰县（下萨克森州）、梅克伦堡湖区县（梅前州）和莱茵-锡格县（北威州）。', 0, 1, NOW(), NOW()),
  ('eb1d77c0-70d1-4d52-bfb4-1bbc4f23203a', 'b09aebcc-af92-4eb4-930f-261e53c5ed0d', 'Für wie viele Jahre wird der Landtag in Schleswig-Holstein gewählt?', '石勒苏益格-荷尔斯泰因州的州议会每隔多少年选举一次？', '石勒苏益格-荷尔斯泰因州州议会的立法周期为5年。', 0, 2, NOW(), NOW()),
  ('faeac95c-b905-44cd-80ac-9f0775059cc3', 'b09aebcc-af92-4eb4-930f-261e53c5ed0d', 'Ab welchem Alter darf man in Schleswig-Holstein bei Kommunalwahlen wählen?', '在石勒苏益格-荷尔斯泰因州，年满多少岁可以参加地方选举？', '在石勒苏益格-荷尔斯泰因州，参加地方选举的最低年龄是16岁。', 0, 3, NOW(), NOW()),
  ('d4444d76-cbb6-462d-a698-58510a1c09a7', 'b09aebcc-af92-4eb4-930f-261e53c5ed0d', 'Welche Farben hat die Landesflagge von Schleswig-Holstein?', '石勒苏益格-荷尔斯泰因州的州旗是什么颜色的？', '石勒苏益格-荷尔斯泰因州的州旗由上蓝、中白、下红三条水平色带组成。', 0, 4, NOW(), NOW()),
  ('637b262f-44b6-497b-a7fe-0ff987de18e6', 'b09aebcc-af92-4eb4-930f-261e53c5ed0d', 'Wo können Sie sich in Schleswig-Holstein über politische Themen informieren?', '在石勒苏益格-荷尔斯泰因州，您可以从哪里获取政治主题的信息？', '在石勒苏益格-荷尔斯泰因州，负责提供政治教育的机构是“州政治教育专员” (Landesbeauftragte für politische Bildung)，其职能与其他州的政治教育中心类似。', 0, 5, NOW(), NOW()),
  ('25ef4763-d084-4309-ad9c-1b8cbad03969', 'b09aebcc-af92-4eb4-930f-261e53c5ed0d', 'Die Landeshauptstadt von Schleswig-Holstein heißt...', '石勒苏益格-荷尔斯泰因州的首府是...', '基尔是石勒苏益格-荷尔斯泰因州的州首府。', 0, 6, NOW(), NOW()),
  ('5b01ea37-d274-4479-9036-f55149ab23c5', 'b09aebcc-af92-4eb4-930f-261e53c5ed0d', 'Welches Bundesland ist Schleswig-Holstein?', '哪个联邦州是石勒苏益格-荷尔斯泰因州？', '地图上数字1指向的区域是德国最北部的联邦州——石勒苏益格-荷尔斯泰因州。', 0, 7, NOW(), NOW()),
  ('2380f514-990c-4c89-879e-91e696b5f2c8', 'b09aebcc-af92-4eb4-930f-261e53c5ed0d', 'Wie nennt man die Regierungschefin/den Regierungschef in Schleswig-Holstein?', '石勒苏益格-荷尔斯泰因州的政府首脑被称为什么？', '石勒苏益格-荷尔斯泰因州的政府首脑被称为“Ministerpräsident(in)”，即州长。', 0, 8, NOW(), NOW()),
  ('495eba77-72c6-4b82-8bf0-98554326f03f', 'b09aebcc-af92-4eb4-930f-261e53c5ed0d', 'Welche Ministerin/welchen Minister hat Schleswig-Holstein nicht?', '石勒苏益格-荷尔斯泰因州没有哪位部长？', '外交为联邦政府专属职权，因此包括石勒苏益格-荷尔斯泰因在内的所有联邦州都没 有外交部长。', 0, 9, NOW(), NOW()),
  ('eec9b3ac-bd87-4c47-bd9d-63a9ac0f66a2', '9ca749ab-6bbb-4e1b-a567-9b473df4dd61', 'Welches Wappen gehört zum Freistaat Thüringen?', '哪个州徽属于图林根自由州？', '图林根州的州徽是在蓝色盾牌上的一只直立的、红白相间的狮子（与黑森州徽类似，但 颜色不同），狮子周围环绕着八颗白色的六角星。', 1, 0, NOW(), NOW()),
  ('ba826b29-1c9a-4a77-abc5-64aed2ad3ac3', '9ca749ab-6bbb-4e1b-a567-9b473df4dd61', 'Welches ist ein Landkreis in Thüringen?', '哪个是图林根州的一个县？', '瓦尔特堡县是图林根州的一个县，著名的瓦尔特堡（马丁·路德曾在此翻译圣经）位于 该县。其他选项分别属于：阿默尔兰县（下萨克森州）、阿尔多廷县（巴伐利亚州）和北弗里斯兰县 （石荷州）。', 0, 1, NOW(), NOW()),
  ('d6aab2d1-f927-4d02-b8b8-935cdef814d5', '9ca749ab-6bbb-4e1b-a567-9b473df4dd61', 'Für wie viele Jahre wird der Landtag in Thüringen gewählt?', '图林根州的州议会每隔多少年选举一次？', '图林根州州议会的立法周期为5年。', 0, 2, NOW(), NOW()),
  ('c2f8592d-5268-46e1-ac22-3a011de97f7a', '9ca749ab-6bbb-4e1b-a567-9b473df4dd61', 'Ab welchem Alter darf man in Thüringen bei Kommunalwahlen wählen?', '在图林根州，年满多少岁可以参加地方选举？', '在图林根州，参加地方选举的最低年龄是16岁。', 0, 3, NOW(), NOW()),
  ('3161dbeb-5391-4214-9dd5-19947ee416be', '9ca749ab-6bbb-4e1b-a567-9b473df4dd61', 'Welche Farben hat die Landesflagge von Thüringen?', '图林根州的州旗是什么颜色的？', '图林根州的州旗由上白下红两条水平色带组成，颜色来源于州徽上狮子的颜色。', 0, 4, NOW(), NOW()),
  ('a6e0bac8-9b9e-4f68-8166-fea371de3499', '9ca749ab-6bbb-4e1b-a567-9b473df4dd61', 'Wo können Sie sich in Thüringen über politische Themen informieren?', '在图林根州，您可以从哪里获取政治主题的信息？', '州政治教育中心是为公民提供政治教育和中立信息的官方机构。', 0, 5, NOW(), NOW()),
  ('d66e4bc3-dd53-405d-a5c2-a83647e4837b', '9ca749ab-6bbb-4e1b-a567-9b473df4dd61', 'Die Landeshauptstadt von Thüringen heißt...', '图林根州的首府是...', '埃尔福特是图林根州的州首府和最大城市。', 0, 6, NOW(), NOW()),
  ('0db7e58a-d95d-4986-82b0-3d9e022a64b7', '9ca749ab-6bbb-4e1b-a567-9b473df4dd61', 'Welches Bundesland ist Thüringen?', '哪个联邦州是图林根州？', '地图上数字2指向的区域是位于德国中部的图林根州，被称为“德国的绿色心脏”。', 0, 7, NOW(), NOW()),
  ('aec14f81-7744-484d-a7e0-725934576e64', '9ca749ab-6bbb-4e1b-a567-9b473df4dd61', 'Wie nennt man die Regierungschefin/den Regierungschef in Thüringen?', '图林根州的政府首脑被称为什么？', '图林根州的政府首脑被称为“Ministerpräsident(in)”，即州长。', 0, 8, NOW(), NOW()),
  ('28c2c597-a179-485d-b8b1-45385c2e6af5', '9ca749ab-6bbb-4e1b-a567-9b473df4dd61', 'Welche Ministerin/welchen Minister hat Thüringen nicht?', '图林根州没有哪位部长？', '在德国的政治体制中，外交由联邦政府负责，各联邦州不设立外交部和外交部长。', 0, 9, NOW(), NOW());
